// лёгкая тактильная отдача на нажатия (где поддерживается)
function haptic(ms){
  if(window.FitNative && window.FitNative.haptic && window.FitNative.haptic()) return;
  try{ navigator.vibrate && navigator.vibrate(ms || 8); }catch(e){}
}
