const OPT_NONE = new Set(['Без инвентаря', 'Без ограничений']);
const OPT_EQUIP = ['Без инвентаря', 'Коврик', 'Гантели', 'Резинки', 'Стул', 'Фитбол', 'Утяжелители', 'Турник'];

