/* ================= ПОКАЗ И СКРЫТИЕ ================= */
// единственный способ управлять видимостью: класс, а не инлайновый display.
// инлайн ломал flex-раскладку и не мог побить .hidden{display:none!important}
function setShown(el, on){
  const node = (typeof el === 'string') ? $(el) : el;
  if(node) node.classList.toggle('hidden', !on);
}

/* ================= ЗАЩИТА ОТ ПОТЕРИ ПРАВОК ================= */
// снимки форм: сравниваем текущее состояние с тем, что было при открытии
const snap = {};
function takeSnap(key, val){ snap[key] = JSON.stringify(val ?? null); }
function isChanged(key, val){ return snap[key] !== undefined && snap[key] !== JSON.stringify(val ?? null); }
function clearSnap(key){ delete snap[key]; }

// спрашивает подтверждение, если что-то менялось; иначе уходит молча
// Формулировка одна на всё приложение: «ещё не сохранены» (а не «не сохранены» —
// прошедшее время звучало как приговор), а кнопки всегда «Выйти без сохранения»
// и «Остаться» — вместо пяти разных способов сказать «отменить».
async function leaveGuard(changed, go, what){
  if(changed){
    const ok = await appDialog(
      t('common.unsaved',{what:what || t('common.changes')}),
      {confirm: true, okText: t('common.leaveWithoutSaving'), cancelText: t('common.stay')}
    );
    if(!ok) return false;
  }
  go();
  return true;
}

// текст в полях ИИ-экрана считается несохранённой работой
function aiScreenDirty(ids){
  return ids.some(id => { const el = $(id); return el && (el.value || '').trim(); });
}

/* ================= ПРОВЕРКА ЧИСЛОВЫХ ПОЛЕЙ =================
   Раньше «абв» в поле повторений молча превращалось в 1 при сохранении.
   Теперь поле краснеет прямо во время ввода и говорит, что от него хотят,
   а сохранение не проходит, пока ошибка не исправлена. */
const NUM_RULES = {
  int:   {re: /^\s*\d{1,4}\s*$/,                          key: 'num.int'},
  range: {re: /^\s*\d{1,3}\s*(?:[-–—]\s*\d{1,3}\s*)?$/, key: 'num.range'},
  dec:   {re: /^\s*\d{1,4}(?:[.,]\d{1,2})?\s*$/,         key: 'num.dec'}
};
function markNum(el){
  const kind = el.dataset.numKind;
  const rule = NUM_RULES[kind];
  if(!rule) return true;
  const raw = el.value;
  const empty = !raw.trim();
  const bad = empty ? !!el.dataset.numReq : !rule.re.test(raw);
  const field = el.closest('.field') || el.parentElement;
  field.classList.toggle('bad', bad);
  let hint = field.querySelector('.field-err');
  if(bad){
    if(!hint){
      hint = document.createElement('p');
      hint.className = 'field-err';
      field.appendChild(hint);
    }
    hint.innerHTML = icon('alert') + '<span></span>';
    hint.querySelector('span').textContent = empty ? t('num.required') : t(rule.key);
  } else if(hint) hint.remove();
  return !bad;
}
function guardNum(id, kind, required){
  const el = $(id);
  if(!el) return;
  el.dataset.numKind = kind;
  if(required) el.dataset.numReq = '1';
  const check = () => markNum(el);
  el.addEventListener('input', check);
  el.addEventListener('blur', check);
}
// проверяет все видимые числовые поля экрана; на первую ошибку — прокрутка и фокус
function numFieldsOk(scopeId){
  const scope = $(scopeId);
  if(!scope) return true;
  let first = null;
  scope.querySelectorAll('[data-num-kind]').forEach(el => {
    if(el.offsetParent === null) return; // поле сейчас скрыто — не наша забота
    if(!markNum(el) && !first) first = el;
  });
  if(first){
    try{ first.scrollIntoView({block: 'center', behavior: 'smooth'}); }catch(_){}
    first.focus();
    return false;
  }
  return true;
}

/* ================= КАСКАД НАСТРОЕК ЗВУКА (общий для трёх мест) ================= */
// показывает/прячет вложенные блоки по состоянию тумблеров; сама раскладка одна и та же
// в профиле, на экране старта и в попапе на тренировке — меняются только префикс id и что именно сохраняется
function syncSoundCascade(p){
  const on = $(p + 'SoundOn').classList.contains('on');
  setShown(p + 'SoundBox', on);
  if(!on) return;
  setShown(p + 'FxField', $(p + 'FxOn').classList.contains('on'));
}

/* ================= ДИАЛОГИ ПРИЛОЖЕНИЯ (вместо системных) ================= */
function appDialog(msg, opts = {}){
  return new Promise(res => {
    $('dlgMsg').textContent = msg;
    const codeEl = $('dlgCode');
    if(opts.code){ setShown(codeEl, true); codeEl.value = opts.code; }
    else setShown(codeEl, false);
    // opts.type — фраза, которую надо набрать: пока она не совпала, кнопка не работает
    const typed = $('dlgType');
    setShown('dlgTypeBox', !!opts.type);
    typed.oninput = null;
    if(opts.type){
      typed.value = '';
      $('dlgTypeLabel').textContent = t('dialog.type',{text:opts.type});
      const check = ()=>{ $('dlgOk').disabled = typed.value.trim().toLowerCase() !== opts.type.toLowerCase(); };
      typed.oninput = check;
      check();
      setTimeout(()=> typed.focus(), 80);
    } else {
      $('dlgOk').disabled = false;
    }
    $('dlgOk').textContent = opts.okText || t('common.ok');
    if(opts.cancelText) $('dlgCancel').textContent = opts.cancelText;
    else $('dlgCancel').textContent = t('common.cancel');
    setShown('dlgCancel', opts.confirm);
    $('dlg').classList.add('open');
    const done = v => {
      $('dlg').classList.remove('open');
      $('dlgOk').onclick = $('dlgCancel').onclick = $('dlg').onclick = null;
      $('dlgOk').disabled = false;
      setShown('dlgTypeBox', false);
      typed.oninput = null;
      res(v);
    };
    $('dlgOk').onclick = () => done(true);
    $('dlgCancel').onclick = () => done(false);
    $('dlg').onclick = e => { if(e.target === $('dlg')) done(opts.confirm ? false : true); };
  });
}
const appAlert = (m, o) => appDialog(m, o);
// Подтверждение действия. Кнопка по умолчанию — «Подтвердить», а не «Да»:
// «Да» была безопасна только когда текст вопроса читается как «да/нет», а
// у нас — «Удалить программу?».
const appConfirm = (m, o) => appDialog(m, {confirm: true, okText: t('common.confirm'), cancelText: t('common.cancel'), ...o});
const screens = ['scrMenu','scrPrograms','scrStore','scrStoreItem','scrAccount','scrStart','scrWork','scrFinish','scrBuilder','scrProgSettings','scrExercise','scrImages','scrAI','scrLegal','scrStats','scrUserEdit','scrTrainer','scrClient','scrTrainerPage','scrPublish','scrMyCatalog','scrOnboard'];
/* Корневые разделы: только у них внизу док и нет собственной панели действий.

   «Подопечные» — раздел, который есть не у всех: он появляется вместе с режимом
   тренера и исчезает вместе с ним. Держать его в списке всегда можно и нужно —
   иначе show() не узнает в нём корневой экран, — а прячет кнопку сам док. */
const ROOT_TABS = ['scrMenu','scrPrograms','scrTrainer','scrStats','scrAccount'];
// Глубина истории относительно «Сегодня»: лежит прямо в состоянии записи, поэтому
// переживает и системную кнопку «назад», и перезаход по истории.
let navDepth = 0;
// Путь по экранам, каким его видит человек. Нужен, чтобы возврат на экран, где
// он уже был, НЕ добавлял запись в историю: «конструктор → настройки → назад →
// упражнение → назад → настройки → назад» копил по записи на каждый шаг, и
// потом системная кнопка «назад» требовала столько же нажатий, сколько было
// переходов. Теперь такой возврат отматывает историю назад, а не удлиняет её.
let navStack = ['scrMenu'];
// Вкладка — ДРУГОЙ ВИД ТОГО ЖЕ МЕСТА, а не шаг вглубь: «Вручную / Через ИИ / Из
// видео» переключают способ, но человек всё это время делает одно и то же дело.
// Поэтому переключение ЗАМЕНЯЕТ текущую запись истории, а не добавляет новую:
// иначе двадцать переключений туда-сюда давали двадцать записей, и «назад»
// приходилось жать двадцать два раза вместо одного (измерено).
let tabSwitch = false;
function asTab(fn){
  tabSwitch = true;
  try{ fn(); } finally { tabSwitch = false; }
}
try{ history.replaceState({scr:'scrMenu', d:0}, ''); }catch(e){}
// Что считается несохранённой работой на каждом экране. Раньше эту проверку знали
// только кнопки «назад» внутри приложения, а системная кнопка «назад» звала show()
// напрямую — и набранная программа исчезала молча.
const LEAVE_GUARDS = {
  scrBuilder:  ()=> programDirty() ? {what:t('builder.programChanges'), clean:()=> clearSnap('program')} : null,
  scrExercise: ()=> exDirty() ? {what:t('exercise.changes'), clean:()=>{ dropFreshEx(); exDraft = null; exIdx = -1; exOrig = ''; exFromWork = false; }} : null,
  scrUserEdit: ()=> userDirty() ? {what:t('profile.changes')} : null,
  scrAI:       ()=> (AI_SOURCES[aiSrc] && aiScreenDirty(AI_SOURCES[aiSrc].dirty)) ? {what:t('ai.filledRequest')} : null
};
let guardBypass = false; // второй заход после подтверждения — уже не спрашиваем
// Жест «назад» и системная кнопка закрывают открытый попап, а не уводят с экрана.
// Закрываем ровно тем же путём, что и собственная кнопка отмены: на ней у части
// попапов висит возврат состояния, и простое снятие класса его бы потеряло.
// #dlg проверяем первым: он лежит выше остальных (z-index 90) и может быть открыт
// поверх другого попапа.
function dismissTopModal(){
  const dlg = $('dlg');
  const m = dlg.classList.contains('open')
    ? dlg
    : [...document.querySelectorAll('.modal.open')].pop();
  if(!m) return false;
  // попап хода работы: пока идёт запрос к ИИ, закрывать нечего — жест просто гасим
  if(m.dataset.locked === '1') return true;
  if(m === dlg){
    // тот же путь, что и нажатие мимо карточки: промис appDialog обязан завершиться
    m.dispatchEvent(new MouseEvent('click', {bubbles: false}));
    return true;
  }
  const cancel = m.querySelector('.modal-btn');
  if(cancel){ cancel.click(); return true; }
  m.classList.remove('open');
  return true;
}

// Системная кнопка «назад» забирает у истории одну запись — и только тогда срабатывает
// popstate. На корневом экране записей нет вообще: приложение просто сворачивалось,
// даже когда поверх него был открыт попап. Поэтому попап сам добавляет себе запись —
// её и заберёт жест «назад», а обработчик ниже закроет попап.
let skipPop = 0;   // наш собственный history.back(), а не жест человека
let modalsOpen = false;
let lockedY = 0;
// Пока страница зафиксирована, у неё нет прокрутки — и нижняя панель кнопок,
// которая держалась на position:sticky, теряет то, к чему прилипала: она
// подпрыгивала вверх ровно на величину прокрутки. На экране, пролистанном на
// треть, «Готово» с открытием любого попапа улетало на середину экрана.
// Поэтому на время попапа панель замирает там, где её видно.
function freezeSticky(on){
  document.querySelectorAll('.builder-actions, .actions').forEach(el => {
    if(on){
      if(!el.offsetParent) return;
      const r = el.getBoundingClientRect();
      el.dataset.froze = '1';
      el.style.position = 'fixed';
      // top у fixed задаёт край ПОЛЯ, а не рамки: собственный верхний отступ
      // панели сдвинул бы её ещё на свою величину вниз
      el.style.margin = '0';
      el.style.top = Math.round(r.top) + 'px';
      el.style.left = Math.round(r.left) + 'px';
      el.style.width = Math.round(r.width) + 'px';
    } else if(el.dataset.froze){
      delete el.dataset.froze;
      el.style.position = el.style.top = el.style.left = el.style.width = el.style.margin = '';
    }
  });
}
function lockPage(on){
  const b = document.body;
  if(on === b.classList.contains('modal-lock')) return;
  if(on){
    lockedY = window.scrollY || window.pageYOffset || 0;
    freezeSticky(true);          // замеряем ДО фиксации страницы
    b.style.top = `-${lockedY}px`;
    b.classList.add('modal-lock');
  } else {
    b.classList.remove('modal-lock');
    b.style.top = '';
    window.scrollTo(0, lockedY);
    freezeSticky(false);
  }
}
new MutationObserver(()=>{
  const now = !!document.querySelector('.modal.open');
  if(now === modalsOpen) return;
  modalsOpen = now;
  lockPage(now);
  if(now){
    try{ history.pushState({scr: show._last, d: navDepth, m: 1}, ''); }catch(e){}
    return;
  }
  // Попап закрыли кнопкой — лишнюю запись надо убрать. Но только если она всё ещё
  // сверху: попап мог увести на другой экран (например, «Вручную» → конструктор),
  // и тогда наш history.back() отменил бы этот переход.
  if(history.state && history.state.m){
    skipPop++;
    try{ history.back(); }catch(e){ skipPop = Math.max(0, skipPop - 1); }
  }
}).observe(document.documentElement, {subtree: true, attributes: true, attributeFilter: ['class']});

window.addEventListener('popstate', async e => {
  if(skipPop > 0){ skipPop--; return; }   // это мы сами сняли запись закрытого попапа
  // открытый попап забирает жест себе — экран под ним остаётся на месте
  if(document.querySelector('.modal.open')){
    try{ history.pushState(e.state || {scr: show._last, d: navDepth}, ''); }catch(_){}
    dismissTopModal();
    return;
  }
  if($('scrWork').classList.contains('on')){
    // назад во время тренировки — спрашиваем, а не выбрасываем
    try{ history.pushState({scr:'scrWork'}, ''); }catch(_){}
    exitWorkout();
    return;
  }
  let targetScreen = (e.state && e.state.scr) || 'scrMenu';
  navDepth = (e.state && typeof e.state.d === 'number') ? e.state.d : 0;
  {
    const at = navStack.lastIndexOf(targetScreen);
    if(at >= 0) navStack.length = at + 1; else navStack = [targetScreen];
  }
  // На эти экраны нельзя вернуться «из истории» — там нет живого состояния.
  // Исключение: тренировка, которая ИДЁТ ПРЯМО СЕЙЧАС. С неё можно уйти в
  // редактор упражнения, и жест «назад» обязан вернуть на неё, а не выбросить
  // на «Сегодня», бросив занятие на середине.
  if((targetScreen === 'scrWork' && !state.live) || targetScreen === 'scrFinish' || targetScreen === 'scrOnboard') targetScreen = 'scrMenu';

  if(!guardBypass){
    const cur = screens.find(id => $(id) && $(id).classList.contains('on'));
    let g = null;
    try{ g = cur && LEAVE_GUARDS[cur] ? LEAVE_GUARDS[cur]() : null; }catch(_){ g = null; }
    if(g){
      // возвращаем позицию в истории, чтобы «Вернуться» действительно вернуло
      navDepth++;
      try{ history.pushState({scr: cur, d: navDepth}, ''); }catch(_){}
      const ok = await appDialog(
        t('common.unsaved',{what:g.what}),
        {confirm: true, okText: t('common.leaveWithoutSaving'), cancelText: t('common.stay')}
      );
      if(!ok) return;
      if(g.clean) g.clean();
      guardBypass = true;
      history.back();
      return;
    }
  }
  guardBypass = false;
  show(targetScreen, false);
});
// «Назад» и «Готово» на вложенном экране ВОЗВРАЩАЮТ, а не переходят: если нужный
// экран лежит в пути прямо под текущим, снимаем запись истории вместо того, чтобы
// класть новую. Иначе «конструктор → настройки → назад → упражнение → назад» копил
// по записи на каждый шаг: сорок переходов давали сорок одну запись, и системная
// кнопка «назад» тридцать раз подряд не выводила из конструктора.
// Экран покажет сам popstate — здесь только отматываем.
function goBackTo(id){
  if(navStack.length > 1 && navStack[navStack.length - 2] === id && show._last === navStack[navStack.length - 1]){
    try{ history.back(); return; }catch(e){}
  }
  show(id);
}

function show(id, push = true){
  // Ушли из редактора, не сохранив только что заведённое упражнение, — строку в
  // списке не оставляем. Ловим здесь, а не в кнопке «назад»: уйти можно ещё
  // жестом и системной кнопкой, и тогда в программе оставалось «Без названия».
  // Переключение ВКЛАДКИ уходом не считается: это тот же экран в другом виде.
  // Из-за этого ломалась правка упражнения прямо с тренировки: сходил на вкладку
  // «Через ИИ» и обратно — exFromWork терялся, и «Готово» уводило в конструктор,
  // бросив тренировку на середине.
  if(show._last === 'scrExercise' && id !== 'scrExercise' && !tabSwitch){ dropFreshEx(); exFromWork = false; }
  if(push && show._last !== id){
    if(tabSwitch){
      navStack[navStack.length - 1] = id;
      try{ history.replaceState({scr: id, d: navDepth}, ''); }catch(e){}
    } else {
      navStack.push(id);
      navDepth++;
      try{ history.pushState({scr: id, d: navDepth}, ''); }catch(e){}
    }
  }
  if(show._last !== id) stopFinishFx(); // праздник остаётся на своём экране
  show._last = id;
  screens.forEach(s => $(s).classList.toggle('on', s===id));
  // верхняя полоса нужна ровно одному экрану — тренировке
  setShown('topBar', id==='scrWork');
  $('btnExit').classList.toggle('on', id==='scrWork');
  $('btnSoundW').classList.toggle('on', id==='scrWork');
  $('btnMicW').classList.toggle('on', id==='scrWork' && !!SR);
  document.querySelectorAll('.dock-btn').forEach(b => {
    const on = b.dataset.scr === id;
    b.classList.toggle('act', on);
    b.setAttribute('aria-current', on ? 'page' : 'false');
  });
  syncDock();
  // тренировка живёт ровно в один экран телефона: скроллится только описание,
  // а панель управления всегда на одном месте (см. body.screen-work в стилях)
  document.body.classList.toggle('screen-work', id==='scrWork');
  if(ROOT_TABS.includes(id)) prepTab(id);
}

// содержимое вкладки всегда свежее — неважно, пришли в неё по доку, по кнопке
// внутри приложения или системным «назад»
function prepTab(id){
  try{
    if(id === 'scrStats'){ renderStats(); renderWeight(); renderWellness(); renderPhotos(); }
    else if(id === 'scrPrograms'){ renderMine(); }
    else if(id === 'scrAccount'){
      switchMoreTab(typeof moreTab === 'string' ? moreTab : 'me');
      renderUsers();
      renderTrainerCard();
      // звук и управление без рук переехали сюда из «Настроек»
      syncSettingsForm();
      fillLiveSoundCascade('st');
      $('hfHint').textContent = hfHintText(hfMode);
      document.querySelectorAll('#hfSeg button').forEach(b => b.classList.toggle('act', b.dataset.hf === hfMode));
    }
    else if(id === 'scrTrainer'){ refreshClientsScreen(); }
    else if(id === 'scrMenu'){ renderGreeting(); renderToday(); }
  }catch(e){}
}

/* ---- док: показываем только на корневых разделах и только без клавиатуры ----
   Правило владельца: две закреплённые полосы одновременно недопустимы. Панель
   действий есть у каждого глубокого экрана, поэтому там дока нет вовсе, а на
   корневых нет панели действий. Клавиатура — третий случай: пока в фокусе поле
   ввода, док уезжает, иначе он сядет поверх клавиатуры на «Настройках». */
function kbFocused(){
  const el = document.activeElement;
  return !!(el && el.matches && el.matches('input:not([type=range]):not([type=file]):not([type=checkbox]),textarea'));
}
// Кнопка «Подопечные» живёт вместе с режимом тренера. Зовётся оттуда же, откуда
// перерисовывается карточка тренера, — чтобы появляться в тот же миг, а не после
// перезапуска.
function syncDockTabs(){
  const b = document.querySelector('.dock-btn[data-scr="scrTrainer"]');
  if(b) setShown(b, trainerOn());
}

function syncDock(){
  setShown('dock', ROOT_TABS.includes(show._last) && !kbFocused());
}
document.addEventListener('focusin', ()=> syncDock());
document.addEventListener('focusout', ()=> setTimeout(syncDock, 60));

// Переход по доку. Вкладки не копят историю: поверх «Сегодня» живёт максимум одна
// запись, а «назад» с любой вкладки возвращает на «Сегодня».
function goTab(id){
  const cur = show._last;
  if(cur === id){
    try{ window.scrollTo({top: 0, behavior: 'smooth'}); }catch(e){ window.scrollTo(0, 0); }
    return;
  }
  if(!ROOT_TABS.includes(cur)){
    // возврат из глубины: текущая запись становится «Сегодня», вкладка ложится поверх
    navDepth = 0;
    navStack = ['scrMenu'];
    try{ history.replaceState({scr:'scrMenu', d:0}, ''); }catch(e){}
    if(id === 'scrMenu'){ show('scrMenu', false); window.scrollTo(0, 0); return; }
    show(id, true);
    window.scrollTo(0, 0);
    return;
  }
  if(id === 'scrMenu'){
    if(navDepth > 0){ history.go(-navDepth); return; }
    navStack = ['scrMenu'];
    show('scrMenu', false);
    window.scrollTo(0, 0);
    return;
  }
  if(navDepth > 0){
    navDepth = 1;
    navStack = ['scrMenu', id];
    try{ history.replaceState({scr: id, d: 1}, ''); }catch(e){}
    show(id, false);
  } else {
    show(id, true);
  }
  window.scrollTo(0, 0);
}

/* ================= ЭКРАН 2: СТАРТ ================= */

// с какой вкладки открыли программу — туда и вернёт «назад» с экрана старта
let startFrom = 'scrMenu';
function openStart(raw){
  if(ROOT_TABS.includes(show._last)) startFrom = show._last;
  applyProgressionAll();
  applyAudioFromUser(curUser());
  state.raw = raw;
  const plans = normPlans(raw);
  state.planIdx = defaultPlanIdx(plans, raw);
  $('startNum').textContent = '';
  $('startTitle').textContent = raw.name;
  renderPlanRow();
  renderProgSteps();
  renderStartInfo();
  syncPrefs();
  show('scrStart');
  window.scrollTo(0, 0); // иначе экран открывается там же, где был прокручен предыдущий, — мимо названия
}

// по умолчанию выбираем вариант, в чьи дни попадает сегодня
function defaultPlanIdx(plans, prog){
  // режим ротации: варианты идут по очереди A-B-A-B независимо от календаря,
  // пропуск дня не сбивает очередь
  if(prog && prog.rotate && plans.length > 1){
    const next = (typeof prog.rotIdx === 'number') ? prog.rotIdx : 0;
    return ((next % plans.length) + plans.length) % plans.length;
  }
  const today = DAYS[(new Date().getDay() + 6) % 7];
  const i = plans.findIndex(pl => (pl.days || []).includes(today));
  return i >= 0 ? i : 0;
}

function renderPlanRow(){
  const plans = normPlans(state.raw);
  const block = $('planBlock'), row = $('planRow');
  row.innerHTML = '';
  if(plans.length < 2){ setShown(block, false); return; }
  setShown(block, true);
  plans.forEach((pl, i)=>{
    const b = document.createElement('button');
    b.className = 'load-chip plan-chip';
    const rotOn = state.raw.rotate && plans.length > 1;
    let lbl = (!rotOn && pl.days && pl.days.length) ? pl.days.map(canonicalLabel).join('·') : `${t('builder.variant')} ${i+1}`;
    if(rotOn && i === defaultPlanIdx(plans, state.raw)) lbl += ' • ' + t('start.current');
    b.textContent = lbl;
    b.classList.toggle('act', state.planIdx === i);
    b.onclick = ()=>{ state.planIdx = i; renderPlanRow(); renderStartInfo(); };
    row.appendChild(b);
  });
}

// Нагрузка одного упражнения в том же виде, в каком она появится на тренировке.
// Отдельная функция не даёт обзору и таймеру разойтись в формулах прогрессии.
function exerciseLoad(p, ex){
  const on = progAxis(ex) !== 'none';
  const timed = ex.type === 'time';
  const load = {reps:'', sec:0, kg:0};
  if(timed){
    load.sec = on && progStepSize(ex, 'time') > 0
      ? getExProgValue(p.id, ex, p, 'time')
      : progBaseValue(ex, 'time');
  } else {
    load.reps = on && progStepSize(ex, 'reps') > 0
      ? progressedRepsRange(p.id, ex, p)
      : normValue(ex.value, 'reps');
  }
  if(hasWeight(ex)){
    load.kg = on && progStepSize(ex, 'weight') > 0
      ? getExProgValue(p.id, ex, p, 'weight')
      : progBaseValue(ex, 'weight');
  }
  return load;
}

// Снимок нужен следующей тренировке для честного «было → сегодня». Старые записи
// снимка не имеют; для них ниже есть совместимый расчёт по предыдущему шагу.
function workoutLoadSnapshot(p, planIdx){
  const pl = normPlans(p)[planIdx] || normPlans(p)[0];
  return ((pl && pl.exercises) || []).map((ex, i) => {
    const v = exerciseLoad(p, ex);
    return {i, n:ex.name || '', reps:v.reps || '', sec:+v.sec || 0, kg:+v.kg || 0};
  });
}

function previousWorkoutLoad(p, planIdx){
  const hist = (stats.history || []).filter(h => h.pid === p.id && (+h.plan || 0) === planIdx);
  const last = hist[hist.length - 1];
  if(last && Array.isArray(last.load)) return {first:false, exact:true, rows:last.load};
  const done = (p.stats && p.stats.completions) || 0;
  if(!hist.length && done <= 0) return {first:true, exact:false, rows:[]};
  const prev = Object.assign({}, p, {stats:Object.assign({}, p.stats || {}, {completions:Math.max(0, done - 1)})});
  return {first:false, exact:false, rows:workoutLoadSnapshot(prev, planIdx)};
}

function loadTargetText(ex, v){
  const bits = [];
  if(ex.type === 'time') bits.push(`${v.sec} ${t('store.secShort')}`);
  else bits.push(`${v.reps} ${t('workout.repsShort')}`);
  if(v.kg > 0) bits.push(`${fmtKg(v.kg)} ${t('progress.kg')}`);
  let out = bits.join(' × ');
  if(ex.perSide) out += ' ' + t('store.perSide');
  return out;
}

function loadDelta(a, b){
  if(!a) return {text:'', dir:'same'};
  const bits = [];
  const moves = [];
  if(String(a.reps || '') !== String(b.reps || '')){
    bits.push(t('start.deltaReps',{before:a.reps,today:b.reps}));
    const av = parseValue(a.reps), bv = parseValue(b.reps);
    moves.push(bv.min - av.min, bv.max - av.max);
  }
  if((+a.sec || 0) !== (+b.sec || 0)){
    bits.push(t('start.deltaTime',{before:a.sec,today:b.sec})); moves.push((+b.sec || 0) - (+a.sec || 0));
  }
  if((+a.kg || 0) !== (+b.kg || 0)){
    bits.push(t('start.deltaWeight',{before:fmtKg(a.kg),today:fmtKg(b.kg)})); moves.push((+b.kg || 0) - (+a.kg || 0));
  }
  const directional = moves.filter(x => x !== 0);
  const dir = directional.length && directional.every(x => x > 0) ? 'up'
    : directional.length && directional.every(x => x < 0) ? 'down'
    : directional.length ? 'mixed' : 'same';
  return {text:bits.join(' · '), dir};
}

function estimatedWorkoutMinutes(p, planIdx, rows){
  const own = (stats.history || []).filter(h => h.pid === p.id && (+h.plan || 0) === planIdx
    && +h.sec > 59 && +h.sec < 6 * 3600).slice(-5);
  if(own.length){
    const avg = own.reduce((n, h) => n + h.sec, 0) / own.length;
    return {n:Math.max(1, Math.round(avg / 60)), history:true, samples:own.length};
  }
  const pl = normPlans(p)[planIdx] || normPlans(p)[0];
  let sec = 0;
  const lastMain = ((pl && pl.exercises) || []).map((ex, i) => ex.warmup ? -1 : i).filter(i => i >= 0).pop();
  ((pl && pl.exercises) || []).forEach((ex, i) => {
    const v = rows[i] || exerciseLoad(p, ex);
    const sets = Math.max(1, parseInt(ex.sets) || 1);
    const rounds = ex.warmup ? 1 : Math.max(1, +pl.rounds || 1);
    const sides = ex.perSide ? 2 : 1;
    const work = ex.type === 'time' ? (+v.sec || 1) * sides : Math.max(1, parseValue(v.reps).min) * 3 * sides;
    sec += work * sets * rounds;
    sec += Math.max(0, sets - 1) * (+ex.rest || 0) * rounds;
    if(ex.warmup || i !== lastMain) sec += exRestAfter(ex) * rounds;
    if(ex.perSide && ex.type === 'time') sec += sideSec * sets * rounds;
  });
  sec += Math.max(0, (+pl.rounds || 1) - 1) * (+pl.roundRest || 0);
  return {n:Math.max(5, Math.round(sec / 300) * 5), history:false, samples:0};
}

function renderStartOverview(){
  const p = state.raw;
  const pl = normPlans(p)[state.planIdx] || normPlans(p)[0];
  if(!p || !pl) return;
  const exercises = pl.exercises || [];
  const current = workoutLoadSnapshot(p, state.planIdx);
  const previous = previousWorkoutLoad(p, state.planIdx);
  const oldByIndex = new Map((previous.rows || []).map(x => [+x.i, x]));
  const changes = [];
  exercises.forEach((ex, i) => {
    const old = oldByIndex.get(i);
    if(old && old.n && ex.name && old.n.trim().toLowerCase() !== ex.name.trim().toLowerCase()) return;
    const delta = loadDelta(old, current[i]);
    if(delta.text) changes.push({i, text:delta.text, dir:delta.dir});
  });

  const workSets = exercises.reduce((n, ex) => n + Math.max(1, parseInt(ex.sets) || 1)
    * (ex.warmup ? 1 : Math.max(1, +pl.rounds || 1)), 0);
  const dur = estimatedWorkoutMinutes(p, state.planIdx, current);
  $('startOverviewSummary').textContent = storeCountText(exercises.length,'exercise') + ' · ' + storeCountText(workSets,'set') + ' · ' + (dur.samples === 1 ? t('start.lastTime',{minutes:dur.n}) : dur.history ? t('start.usualTime',{minutes:dur.n}) : t('start.approxTime',{minutes:dur.n}));

  const change = $('startLoadChange');
  const changeText = text => { change.textContent = text; };
  if(previous.first){
    changeText(t('start.firstWorkout'));
  } else if(changes.length){
    const direction = changes.every(x => x.dir === 'up') ? 'up'
      : changes.every(x => x.dir === 'down') ? 'down' : 'mixed';
    if(direction === 'up'){
      changeText(t('start.loadHigher',{count:changes.length,exercises:t(changes.length === 1 ? 'start.exerciseLocOne' : 'start.exerciseLocMany')}));
    } else if(direction === 'down'){
      changeText(t('start.loadLower',{count:changes.length,exercises:t(changes.length === 1 ? 'start.exerciseLocOne' : 'start.exerciseLocMany')}));
    } else {
      changeText(t('start.loadChanged',{count:changes.length,exercises:t(changes.length === 1 ? 'start.exerciseLocOne' : 'start.exerciseLocMany')}));
    }
  } else if(p.progression){
    const done = (p.stats && p.stats.completions) || 0;
    const left = p.progression - (done % p.progression);
    changeText(t('start.noChangesNext',{count:left,workouts:appLocale === 'ru' ? plural(left,t('start.workoutOne'),t('start.workoutFew'),t('start.workoutMany')) : t(left === 1 ? 'start.workoutOne' : 'start.workoutFew')}));
  } else {
    changeText(t('start.noChangesOff'));
  }

  const box = $('startOverviewList');
  box.innerHTML = '';
  let mainNo = 0;
  exercises.forEach((ex, i) => {
    if(!ex.warmup) mainNo++;
    const sets = Math.max(1, parseInt(ex.sets) || 1);
    const rounds = ex.warmup ? 1 : Math.max(1, +pl.rounds || 1);
    const meta = [];
    if(ex.warmup) meta.push({text:t('store.warmup'), cls:'wm'});
    meta.push({text:loadTargetText(ex, current[i]), cls:''});
    if(!ex.warmup && rounds > 1) meta.push({text:sets > 1 ? `${sets} ${t('start.setShort')} × ${rounds} ${t('start.roundShort')}` : storeCountText(rounds,'round'), cls:''});
    else meta.push({text:storeCountText(sets,'set'), cls:''});
    const delta = changes.find(x => x.i === i);
    const row = document.createElement('div');
    row.className = 'ex-row static' + (ex.warmup ? ' warm' : '');
    const thumb = ex.media && ex.media.kind === 'img'
      ? `<img src="${esc(ex.media.data)}" alt="">`
      : (ex.warmup ? icon('flame') : mainNo);
    row.innerHTML = `<div class="ex-thumb">${thumb}</div><div class="ex-info"><b></b><div class="ex-meta"></div></div>`;
    row.querySelector('b').textContent = ex.name || t('common.exerciseFallback');
    const tags = row.querySelector('.ex-meta');
    const tag = (text, cls) => { const el = document.createElement('span'); if(cls) el.className = cls; el.textContent = text; tags.appendChild(el); };
    meta.forEach(x => tag(x.text, x.cls));
    if(delta) tag(delta.text, 'grow');
    box.appendChild(row);
  });
}

// показывает и позволяет поправить счётчик шагов прогрессии на экране перед стартом.
// Видно, только если у программы есть хоть одно упражнение с осью прогрессии — иначе
// счётчику попросту нечего показывать, а пустая карточка только путает.
function renderProgSteps(){
  const p = state.raw;
  const hasProgAxis = normPlans(p).some(pl => (pl.exercises || []).some(ex => progAxis(ex) !== 'none'));
  const on = p.progression && hasProgAxis;
  setShown('progStepsBlock', on);
  if(!on) return;
  const steps = progSteps(p);
  $('psCount').textContent = steps;
  $('psMinus').disabled = steps <= 0;
}
// кнопки ± двигают РУЧНУЮ ПОПРАВКУ, а не сам счётчик: сам счётчик считается из числа
// пройденных тренировок и пересчитался бы заново, затерев ручное изменение
function bumpProgSteps(dir){
  const p = state.raw;
  const cur = progSteps(p);
  if(dir < 0 && cur <= 0) return;
  p.progStepsAdj = Math.round(+p.progStepsAdj || 0) + dir;
  savePrograms();
  renderProgSteps();
  renderStartOverview();
}

// меню действий на экране просмотра программы — те же пункты, что на карточке
function buildStartMenu(){
  const p = state.raw;
  const menu = $('startMenu');
  menu.innerHTML = '';
  if(!p || p.id === 'warmup'){ $('startMore').style.display = p ? '' : 'none'; }
  const mk = (html2, fn, cls)=>{
    const b = document.createElement('button');
    if(cls) b.className = cls;
    b.innerHTML = html2;
    b.onclick = e => { e.stopPropagation(); closeAllMenus(); fn(); };
    return b;
  };
  const on = progActive(p);
  setShown('startOffChip', !!p && !on);
  // Программа пришла от тренера: показываем, от кого, и даём отчитаться.
  const by = p && p.by ? String(p.by) : '';
  setShown('startByChip', !!by);
  if(by) $('startByName').textContent = by;
  menu.append(
    mk(icon('pencil') + t('common.edit'), ()=> openBuilder(p.id)),
    // тот же переключатель, что в меню карточки в списке: экран программы — второе
    // место, где о программе думают целиком, и искать выключатель в другом списке
    // ради одного действия человек не станет
    mk(icon('power') + (on ? t('programs.disable') : t('programs.enable')), async ()=>{
      p.active = !on;
      await savePrograms();
      buildStartMenu();     // подпись пункта и чип «Откл» на этом же экране
      renderMine();         // список под ним уже перерисован к возврату
      if(on) appAlert(t('programs.disabledAlert'));
    }),
    // Порядок пунктов тот же, что в меню карточки списка: одно и то же меню в двух
    // местах обязано читаться одинаково, иначе рука промахивается.
    mk(icon('copy') + t('common.duplicate'), async ()=>{
      const c = await duplicateProgram(p);
      openBuilder(c.id);
    }),
    mk(icon('share') + t('programs.shareLink'), ()=> exportProgram(p)),
    ...(trainerOn() ? [mk(icon('users') + t('programs.sendClient'), ()=> pickClientFor(p))] : []),
    ...(trainerOn() && !p.storeId ? [mk(icon('crown') + t('programs.submitCatalog'), ()=> openPublish(p))] : []),
    mk(icon('download') + t('programs.saveFile'), ()=> exportProgramFile(p)),
    mk(icon('trash') + t('common.delete'), async ()=>{
      if(!(await appDialog(t('programs.deleteQuestion',{name:p.name}), {confirm: true, okText: t('common.delete'), cancelText: t('common.keep')}))) return;
      customPrograms = customPrograms.filter(x => x.id !== p.id);
      await savePrograms();
      renderMine();
      goTab('scrPrograms');
    }, 'danger')
  );
}

function renderStartInfo(){
  buildStartMenu();
  // описание программы: 4 строки с возможностью раскрыть
  const dBox = $('progDescBox'), dTxt = $('progDescText');
  const d = (state.raw.desc || '').trim();
  if(d){
    dTxt.textContent = d;
    setShown(dBox, true);
    dBox.classList.remove('open');
    $('progDescMore').textContent = t('builder.showFull');
    requestAnimationFrame(()=>{
      const fits = dTxt.scrollHeight <= dTxt.clientHeight + 2;
      setShown('progDescMore', !(fits));
    });
  } else setShown(dBox, false);

  const plans = normPlans(state.raw);
  const pl = plans[state.planIdx];
  const rotOn = state.raw.rotate && plans.length > 1;
  const timeText = pl.time || state.raw.time;
  const daysTxt = rotOn
    ? ((state.raw.days && state.raw.days.length) ? state.raw.days.map(canonicalLabel).join(', ') : '')
    : ((pl.days && pl.days.length) ? pl.days.map(canonicalLabel).join(', ') : '');
  const parts = [timeText, daysTxt].filter(Boolean);
  if(rotOn) parts.push(t('start.variantSequence',{current:state.planIdx+1,total:plans.length}));
  const schedule = parts.join(' · ');
  $('startDesc').textContent = schedule ? t('start.schedule',{schedule}) : '';
  // объём: круги для круговых, подходы для силовых
  const mainEx = (pl.exercises || []).filter(e => !e.warmup);
  const setsTotal = mainEx.reduce((n, e) => n + (parseInt(e.sets) || 1), 0);
  if(pl.rounds > 1 || setsTotal <= mainEx.length){
    $('startVolLabel').textContent = storeCountText(pl.rounds,'round').replace(/^\d+\s+/,'');
    $('startRounds').textContent = pl.rounds;
  } else {
    $('startVolLabel').textContent = storeCountText(setsTotal,'set').replace(/^\d+\s+/,'');
    $('startRounds').textContent = setsTotal;
  }
  const nEx = pl.exercises.length;
  $('startExCount').textContent = nEx;
  $('startExLabel').textContent = storeCountText(nEx,'exercise').replace(/^\d+\s+/,'');
  // обложка программы — если её нет, место не занимаем
  const cov = $('startCover');
  if(state.raw.cover){
    cov.innerHTML = '';
    const img = document.createElement('img');
    img.src = state.raw.cover; img.alt = '';
    cov.appendChild(img);
    setShown(cov, true);
  } else setShown(cov, false);
  renderStartOverview();
}

/* ================= ПОЛЬЗОВАТЕЛИ И ХРАНИЛИЩЕ ================= */
let users = [];
let currentUser = 'f'; // id текущего пользователя; данные пользователей полностью раздельны
const pk = key => key + '_' + currentUser;
const curUser = () => users.find(u => u.id === currentUser) || users[0];
async function saveUsers(){ await kvSet('users', JSON.stringify(users)); }
async function kvDel(key){
  try{ if(window.storage){ await window.storage.delete(key); return; } }catch(e){}
  try{ localStorage.removeItem(key); }catch(e){}
}
function validAge(v){
  if(v === '' || v == null) return null;
  const n = Number(v);
  return Number.isInteger(n) && n >= 5 && n <= 100 ? n : null;
}
// Одноразовая совместимость со старыми профилями и резервными копиями. Точная
// дата используется только в памяти для расчёта, после чего поле удаляется.
function legacyAge(v){
  if(!v) return null;
  const b = new Date(v); if(isNaN(b)) return null;
  const n = new Date();
  let a = n.getFullYear() - b.getFullYear();
  if(n.getMonth() < b.getMonth() || (n.getMonth() === b.getMonth() && n.getDate() < b.getDate())) a--;
  return validAge(a);
}
function profileAge(u){
  return validAge(u && u.age) || legacyAge(u && u.birth);
}
function migrateUserAge(u){
  if(!u || typeof u !== 'object') return u;
  const a = profileAge(u);
  if(a) u.age = a; else delete u.age;
  delete u.birth;
  return u;
}
function localISO(d){
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}
let customPrograms = [];
let stats = {totalSec: 0};
// Старые версии позволяли незаметно записать поправку рабочего веса прямо во время
// тренировки. В редакторе при этом оставалась база (например, 6 кг), а на старте
// показывалось уже 4 кг. Такой второй источник веса удалён.
let progWeights = {};

async function kvGet(key){
  // artifact-хранилище, если доступно; иначе localStorage
  try{
    if(window.storage){
      try{ const r = await window.storage.get(key); return r ? r.value : null; }
      catch(e){ return null; }
    }
  }catch(e){}
  try{ return localStorage.getItem(key); }catch(e){ return null; }
}
async function kvSet(key, val){
  try{ if(window.storage){ await window.storage.set(key, val); return; } }catch(e){}
  try{ localStorage.setItem(key, val); }catch(e){}
}

async function loadData(){
  // данные хранятся раздельно по профилям; старые данные один раз переезжают в текущий профиль
  let progRaw = await kvGet(pk('customPrograms'));
  let statRaw = await kvGet(pk('stats'));
  if(progRaw === null && (await kvGet('migrated')) !== '1'){
    const legacyP = await kvGet('customPrograms');
    const legacyS = await kvGet('stats');
    if(legacyP !== null){ progRaw = legacyP; kvSet(pk('customPrograms'), legacyP); }
    if(legacyS !== null){ statRaw = legacyS; kvSet(pk('stats'), legacyS); }
    kvSet('migrated', '1');
  }
  try{ customPrograms = JSON.parse(progRaw) || []; }catch(e){ customPrograms = []; }
  // Старые личные программы появились до поля locale. Они всё равно одноязычные,
  // поэтому один раз определяем их язык по авторскому тексту. Исторически почти
  // все такие программы русские; латиница без кириллицы считается английской.
  customPrograms.forEach(p => {
    if(!p || p.id === 'warmup' || p.locale === 'ru' || p.locale === 'en') return;
    const plans = Array.isArray(p.plans) ? p.plans : [];
    const sample = [p.name, p.desc].concat(plans.flatMap(pl => (pl.exercises || []).flatMap(ex => [ex.name, ex.desc, ex.mistakes, ex.swapName, ex.swapDesc]))).join(' ');
    p.locale = /[А-Яа-яЁё]/.test(sample) ? 'ru' : 'en';
  });
  try{ stats = JSON.parse(statRaw) || {totalSec:0}; }catch(e){ stats = {totalSec:0}; }
  if(typeof stats.totalSec !== 'number') stats.totalSec = 0;
  if(!Array.isArray(stats.weights)) stats.weights = [];
  if(!Array.isArray(stats.wellness)) stats.wellness = [];
  if(!Array.isArray(stats.history)) stats.history = [];
  if(typeof stats.count !== 'number') stats.count = 0;
  await loadProgWeights();
  await loadTrainer();
  // Док должен знать про режим тренера СРАЗУ. Раньше кнопку показывал только
  // renderTrainerCard(), а он зовётся при входе в «Другое», — и до первого захода
  // туда у тренера было четыре раздела вместо пяти.
  syncDockTabs();
  discardLegacyWeightCorrections();
}

// Удаляем накопленные прежними версиями скрытые поправки веса.
function discardLegacyWeightCorrections(){
  progWeights = {};
  kvSet(pk('progWeights'), '{}');
  if(docMeta && docMeta.progWeights){ delete docMeta.progWeights; kvSet(pk('docMeta'), JSON.stringify(docMeta)); }
  if(Array.isArray(outbox) && outbox.some(x => x.key === 'progWeights')){
    outbox = outbox.filter(x => x.key !== 'progWeights');
    kvSet(pk('outbox'), JSON.stringify(outbox));
  }
}

async function switchUser(id){
  if(currentUser === id) return;
  currentUser = id;
  kvSet('currentUser', id);
  await setAppLocale(profileLocalePreference(curUser()), {persist:false});
  await loadIdentity();
  await loadData();
  await loadPhotos();
  await ensureWarmup();
  applyProgressionAll();
  applyAudioFromUser(curUser());
  const u = curUser();
  applyThemeFor(u);
  renderUsers();
  renderMine();
  renderStats();
  renderWeight();
  renderWellness();
  renderPhotos();
  syncSettingsForm(); // отсчёты и ключ ИИ — у каждого профиля свои
}

// Все профили — одинаковыми строками, у каждой одна и та же кнопка-карандаш.
// Активный отличается не формой, а меткой «сейчас» и рамкой: раньше он жил отдельной
// карточкой сверху, и понять, какой из них выбран, было невозможно.
function renderUsers(){
  const box = $('usersList'); box.innerHTML = '';
  users.forEach(u => {
    const act = u.id === currentUser;
    const row = document.createElement('div');
    row.className = 'user-row' + (act ? ' act' : '');
    const ua = u.photo ? `<img src="${esc(u.photo)}" alt="">` : esc((u.name || '?')[0].toUpperCase());
    const bits = [];
    if(u.gender) bits.push(t(u.gender === 'm' ? 'common.male' : 'common.female'));
    const a = profileAge(u);
    if(a) bits.push(t('profile.ageYears',{count:a,years:appLocale === 'ru' ? plural(a,t('profile.yearOne'),t('profile.yearFew'),t('profile.yearMany')) : (a === 1 ? t('profile.yearOne') : t('profile.yearFew'))}));
    if(!act) bits.push(t('profile.switch'));
    row.innerHTML = `<div class="ua">${ua}</div><div class="ub"><b></b><small>${bits.join(' · ')}</small></div>`
      + (act ? `<span class="u-now">${esc(t('profile.now'))}</span>` : '')
      + `<button class="ue" title="${esc(t('profile.edit'))}">${icon('pencil')}</button>`;
    row.querySelector('b').textContent = u.name || t('profile.noName');
    row.querySelector('.ue').onclick = e => { e.stopPropagation(); openUserEdit(u.id); };
    // нажатие по строке активного профиля переключать некуда — открываем его правку
    row.onclick = ()=> act ? openUserEdit(u.id) : switchUser(u.id);
    box.appendChild(row);
  });
  $('usersHint').textContent = users.length > 1
    ? t('profile.multiHint')
    : t('profile.singleHint');
  renderAccount();
}

function renderAccount(){ renderPlan(); }

// Метрики тела: вес всегда есть, остальное — если человек это записывает.
// Жир и мышцы в процентах показывают умные весы, и без них вес врёт: минус два
// килограмма мышц и минус два килограмма жира на графике веса выглядят одинаково.
function weightSeries(){
  return [
    {k:'w',color:'var(--accent-ink)',label:t('progress.weight'),unit:t('progress.kg')},
    {k:'fat',color:'var(--danger)',label:t('progress.fatShort'),unit:'%'},
    {k:'musc',color:'var(--ok)',label:t('progress.muscleShort'),unit:'%'},
    {k:'waist',color:'var(--accent-ink)',label:t('progress.waistShort'),unit:t('progress.cm')},
    {k:'hips',color:'var(--rest-ink)',label:t('progress.hipsShort'),unit:t('progress.cm')},
    {k:'chest',color:'var(--warn)',label:t('progress.chestShort'),unit:t('progress.cm')}
  ];
}
function fmtMeasure(v){
  return new Intl.NumberFormat(localeTag(), {maximumFractionDigits:1}).format(Number(v));
}
let weightMetric = 'w';

function renderWeight(){
  const ws = stats.weights;
  $('btnWeightHist').innerHTML = icon('pencil') + t('progress.history');
  $('btnShareWeight').innerHTML = icon('share') + t('progress.share');

  if(!ws.length){
    $('weightDelta').textContent = '';
    setShown('weightNowRow', false);   // пустое состояние говорит само за себя ниже
    setShown('weightMeta', false);
    setShown('weightSwitch', false);
    setShown('weightCharts', false);
    setShown('weightActions', false);
    setShown('weightEmpty', true);
    return;
  }
  setShown('weightEmpty', false);
  setShown('weightActions', true);
  setShown('weightNowRow', true);

  const last = ws[ws.length - 1], prev = ws[ws.length - 2];
  $('weightNow').textContent = fmtMeasure(last.w) + ' ' + t('progress.kg');
  if(prev){
    const d = Math.round((last.w - prev.w) * 10) / 10;
    $('weightDelta').textContent = d === 0
      ? t('progress.noChange')
      : t('progress.sinceLast',{delta:(d > 0 ? '+' : '−') + fmtMeasure(Math.abs(d)),unit:t('progress.kg')});
    $('weightDelta').style.color = d > 0 ? 'var(--warn)' : (d < 0 ? 'var(--ok)' : 'var(--muted)');
  } else $('weightDelta').textContent = '';

  // в чипах остались только рост и ИМТ: замеры переехали в переключатель ниже,
  // где у каждого и значение, и свой график — раньше они дублировались дважды
  const meta = [];
  if(stats.height){
    meta.push(`<span class="chip">${esc(t('progress.height'))} <b>${fmtMeasure(stats.height)}</b> ${esc(t('progress.cm'))}</span>`);
    meta.push(`<span class="chip">${esc(t('progress.bmi'))} <b>${fmtMeasure(Math.round(last.w / Math.pow(stats.height/100,2)*10)/10)}</b></span>`);
  }
  $('weightMeta').innerHTML = meta.join('');
  setShown('weightMeta', meta.length);

  // ---- переключатель метрик вместо трёх одинаковых графиков подряд ----
  const avail = weightSeries().filter(s => ws.some(p => p[s.k] != null));
  if(!avail.some(s => s.k === weightMetric)) weightMetric = avail.length ? avail[0].k : 'w';
  $('weightSwitch').innerHTML = avail.map(s => {
    const pts = ws.filter(p => p[s.k] != null);
    const v = pts[pts.length - 1][s.k];
    return `<button type="button" class="wm-chip${s.k === weightMetric ? ' act' : ''}" data-k="${s.k}">
      <span>${s.label}</span><b>${fmtMeasure(v)}<small>${s.unit}</small></b></button>`;
  }).join('');
  setShown('weightSwitch', avail.length > 1);

  const cur = avail.find(s => s.k === weightMetric) || avail[0];
  const have = cur ? ws.map(p => (p[cur.k] != null) ? [p.d, p[cur.k]] : null).filter(Boolean).slice(-30) : [];
  $('weightCharts').innerHTML = have.length ? metricGraph(cur, have) : '';
  setShown('weightCharts', have.length);
}

// Один график метрики: сетка, плавная линия, заливка, подписи концов и дат.
// have2 — вторая линия той же метрики (нижнее давление): это не отдельная метрика,
// а вторая половина одного числа, и врозь «120» и «80» ничего не значат.
function metricGraph(s, have, have2){
  const W = 320, H = 148, padL = 10, padR = 10, padT = 26, padB = 26;
  const pair = Array.isArray(have2) && have2.length === have.length ? have2 : null;
  const vals = have.map(h => h[1]).concat(pair ? pair.map(h => h[1]) : []);
  const first = have[0][1], lastv = have[have.length - 1][1];
  const d = Math.round((lastv - first) * 10) / 10;
  const dCls = d < 0 ? 'down' : (d > 0 ? 'up' : 'flat');
  const du = s.unit;
  const dTxt = d === 0 ? t('progress.noChange') : `${d > 0 ? '+' : '−'}${fmtMeasure(Math.abs(d))} ${du || ''}`.trim();

  let min = Math.min(...vals), max = Math.max(...vals);
  const pad = Math.max((max - min) * 0.15, 0.5);
  min -= pad; max += pad;
  const span = Math.max(max - min, 1);
  const xAt = i => padL + (W - padL - padR) * (have.length === 1 ? 0.5 : i / (have.length - 1));
  const yAt = v => padT + (H - padT - padB) * (1 - (v - min) / span);
  const xy = have.map((h, i) => [Math.round(xAt(i) * 10) / 10, Math.round(yAt(h[1]) * 10) / 10]);

  // сглаженная линия (Catmull-Rom → Bezier)
  const smooth = pts => {
    let p = `M ${pts[0][0]} ${pts[0][1]}`;
    for(let i = 0; i < pts.length - 1; i++){
      const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
      const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
      const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
      p += ` C ${c1x.toFixed(1)} ${c1y.toFixed(1)}, ${c2x.toFixed(1)} ${c2y.toFixed(1)}, ${p2[0]} ${p2[1]}`;
    }
    return p;
  };
  const path = smooth(xy);
  const xy2 = pair ? pair.map((h, i) => [xy[i][0], Math.round(yAt(h[1]) * 10) / 10]) : null;
  const gid = 'g_' + s.k;
  const area = path + ` L ${xy[xy.length-1][0]} ${H-padB} L ${xy[0][0]} ${H-padB} Z`;

  // горизонтальные линии сетки
  let grid = '';
  for(let g = 0; g <= 2; g++){
    const y = padT + (H - padT - padB) * g / 2;
    grid += `<line x1="${padL}" y1="${y}" x2="${W-padR}" y2="${y}" stroke="var(--line)" stroke-width="1" opacity="0.5"/>`;
  }

  const dots = xy.length === 1
    ? `<circle cx="${xy[0][0]}" cy="${xy[0][1]}" r="4" fill="${s.color}"/>`
    : `<circle cx="${xy[0][0]}" cy="${xy[0][1]}" r="3.5" fill="${s.color}"/><circle cx="${xy[xy.length-1][0]}" cy="${xy[xy.length-1][1]}" r="4.5" fill="${s.color}"/>`;

  // подписи значений у концов. У парной метрики подписываем обе половины сразу
  // («120/80»): нижнюю линию без числа рядом всё равно не прочитать.
  const num = v => fmtMeasure(v);
  const capA = pair ? num(first) + '/' + num(pair[0][1]) : num(first);
  const capB = pair ? num(lastv) + '/' + num(pair[pair.length - 1][1]) : num(lastv);
  let labels = '';
  const ly0 = xy[0][1] < padT + 14 ? xy[0][1] + 17 : xy[0][1] - 11;
  labels += `<text x="${xy[0][0]}" y="${ly0}" text-anchor="start" font-size="12" font-weight="700" fill="var(--ink)">${capA}</text>`;
  if(xy.length > 1){
    const lp = xy[xy.length - 1];
    const lyN = lp[1] < padT + 14 ? lp[1] + 17 : lp[1] - 11;
    labels += `<text x="${lp[0]}" y="${lyN}" text-anchor="end" font-size="12" font-weight="700" fill="var(--ink)">${capB}</text>`;
  }
  // даты по краям: без них график не отвечал, за какой срок это движение
  let axis = `<text x="${padL}" y="${H - 6}" text-anchor="start" font-size="10.5" fill="var(--muted)">${shortD(have[0][0])}</text>`;
  if(have.length > 1) axis += `<text x="${W - padR}" y="${H - 6}" text-anchor="end" font-size="10.5" fill="var(--muted)">${shortD(have[have.length-1][0])}</text>`;

  return `<div class="metric-graph">
    <div class="mg-head">
      <span class="mg-delta ${dCls}">${dTxt}</span>
      <small>${s.label} · ${t('progress.records',{count:have.length,records:appLocale === 'ru' ? plural(have.length,t('progress.recordOne'),t('progress.recordFew'),t('progress.recordMany')) : (have.length === 1 ? t('progress.recordOne') : t('progress.recordFew'))})}</small>
    </div>
    <svg viewBox="0 0 ${W} ${H}">
      <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${s.color}" stop-opacity="0.22"/>
        <stop offset="1" stop-color="${s.color}" stop-opacity="0"/>
      </linearGradient></defs>
      ${grid}
      ${xy.length > 1 ? `<path d="${area}" fill="url(#${gid})"/>` : ''}
      ${xy.length > 1 ? `<path d="${path}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>` : ''}
      ${xy2 && xy2.length > 1 ? `<path d="${smooth(xy2)}" fill="none" stroke="${s.color}" stroke-width="2" stroke-dasharray="5 4" stroke-linecap="round" opacity="0.75"/>` : ''}
      ${xy2 ? xy2.map((p, i) => (i === 0 || i === xy2.length - 1) ? `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${s.color}" opacity="0.75"/>` : '').join('') : ''}
      ${dots}
      ${labels}
      ${axis}
    </svg>
  </div>`;
}
/* ================= САМОЧУВСТВИЕ =================
   Давление, пульс и сон. Живут в stats.wellness — внутри уже перечисленного
   в PROFILE_KEYS ключа stats, отдельного ключа хранилища не заводим.
   Запись — одна на день, как у веса: en = {d, sys, dia, pulse, sleep}.
   Давление — не две метрики, а одно число из двух половин: верхнее ведёт график,
   нижнее идёт второй линией и подписывается вместе с ним («120/80»).

   ОЦЕНКИ ДНЯ ЗДЕСЬ НЕТ. Три остальных показателя — измеренные числа: их даёт
   тонометр или телефон, и они сравнимы между собой и между днями. «4 из 5» такой
   же шкалой не является: сегодняшняя четвёрка и прошлогодняя — разные четвёрки,
   а график из них выглядит как измерение. Поле mood в уже сохранённых записях
   остаётся нетронутым — данные не трогаем, просто больше не показываем. */
function wellSeries(){
  return [
    {k:'sys',pair:'dia',color:'var(--danger)',label:t('progress.pressureShort'),unit:''},
    {k:'pulse',color:'var(--accent-ink)',label:t('progress.pulseShort'),unit:t('progress.bpm')},
    {k:'sleep',color:'var(--rest-ink)',label:t('progress.sleepShort'),unit:t('progress.hoursShort')}
  ];
}
const WELL_LIM = {sys: [70, 250], dia: [40, 160], pulse: [30, 220], sleep: [0, 16]};
let wellMetric = 'sys';

const wellList = ()=> Array.isArray(stats.wellness) ? stats.wellness : (stats.wellness = []);
// как метрика читается одной строкой: давление всегда парой, остальное — число с единицей
function wellValue(en, s){
  if(en[s.k] == null) return '';
  const v = fmtMeasure(en[s.k]);
  return s.pair && en[s.pair] != null ? v + '/' + fmtMeasure(en[s.pair]) : v;
}

// Средние за последние 30 дней — то, что показывает главная. Именно среднее, а не
// последняя запись: одно измерение давления ничего не говорит, а месяц — уже картина.
// Окно жёсткое: если за месяц не записано ничего, метрики на главной нет вовсе —
// прошлогодний пульс под заголовком «Прогресс» был бы враньём.
function wellAvg(){
  const from = new Date();
  from.setDate(from.getDate() - 29);
  const lo = localISO(from);
  const ws = wellList().filter(e => e.d >= lo);
  const avg = k => {
    const v = ws.map(e => e[k]).filter(x => x != null);
    return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
  };
  return {sys: avg('sys'), dia: avg('dia'), pulse: avg('pulse'), sleep: avg('sleep')};
}

function renderWellness(){
  const ws = wellList();
  $('btnWellHist').innerHTML = icon('pencil') + t('progress.history');
  $('btnShareWell').innerHTML = icon('share') + t('progress.share');
  if(!ws.length){
    setShown('wellNowRow', false);
    setShown('wellSwitch', false);
    setShown('wellCharts', false);
    setShown('wellActions', false);
    setShown('wellEmpty', true);
    return;
  }
  setShown('wellEmpty', false);
  setShown('wellActions', true);
  setShown('wellNowRow', true);

  // доступна метрика, которую хоть раз записали, — как у веса с обхватами
  const avail = wellSeries().filter(s => ws.some(p => p[s.k] != null));
  if(!avail.length){ setShown('wellNowRow', false); setShown('wellSwitch', false); setShown('wellCharts', false); return; }
  if(!avail.some(s => s.k === wellMetric)) wellMetric = avail[0].k;
  const cur = avail.find(s => s.k === wellMetric);

  $('wellSwitch').innerHTML = avail.map(s => {
    const pts = ws.filter(p => p[s.k] != null);
    const en = pts[pts.length - 1];
    return `<button type="button" class="wm-chip${s.k === wellMetric ? ' act' : ''}" data-k="${s.k}">
      <span>${s.label}</span><b>${wellValue(en, s)}${s.unit ? `<small>${s.unit}</small>` : ''}</b></button>`;
  }).join('');
  setShown('wellSwitch', avail.length > 1);

  // крупная цифра — значение выбранной метрики: та же роль, что у веса в карточке выше
  const pts = ws.filter(p => p[cur.k] != null);
  const lastEn = pts[pts.length - 1];
  $('wellNow').textContent = (wellValue(lastEn, cur) + ' ' + (cur.unit || '')).trim();
  $('wellWhen').textContent = t('progress.recordedOn',{date:shortD(lastEn.d)});
  $('wellWhen').style.color = 'var(--muted)';

  const have = pts.map(p => [p.d, p[cur.k]]).slice(-30);
  const have2 = cur.pair ? pts.map(p => [p.d, p[cur.pair]]).slice(-30) : null;
  const paired = have2 && have2.every(h => h[1] != null) ? have2 : null;
  $('wellCharts').innerHTML = have.length ? metricGraph(cur, have, paired) : '';
  setShown('wellCharts', have.length);
}

// ---- запись самочувствия ----
function openWellAdd(){
  const ws = wellList();
  const today = localISO(new Date());
  const en = ws.find(e => e.d === today) || {};
  // подставляем сегодняшнюю запись, если она уже есть: иначе вторая правка за день
  // выглядела бы как новая пустая форма, а сохранение молча перетирало бы прежнюю
  $('sysInput').value = en.sys || '';
  $('diaInput').value = en.dia || '';
  $('pulseInput').value = en.pulse || '';
  $('sleepInput').value = en.sleep != null ? en.sleep : '';
  $('wellModal').classList.add('open');
}
async function saveWell(){
  const num = (id, k) => {
    const v = parseFloat(String($(id).value).replace(',', '.'));
    return (!isNaN(v) && v >= WELL_LIM[k][0] && v <= WELL_LIM[k][1]) ? Math.round(v * 10) / 10 : null;
  };
  const sys = num('sysInput', 'sys'), dia = num('diaInput', 'dia');
  const pulse = num('pulseInput', 'pulse'), sleep = num('sleepInput', 'sleep');
  // половина давления бессмысленна: «верхнее 130» без нижнего не читается
  if((sys && !dia) || (dia && !sys)){ appAlert(t('well.pressurePair')); return; }
  if(!sys && !pulse && sleep == null){ appAlert(t('well.fillOne')); return; }
  // пульс и давление — сведения о здоровье, как вес и обхваты
  if(!hasConsent('health')) recordConsent('health');
  const ws = wellList();
  const today = localISO(new Date());
  let en = ws.find(e => e.d === today);
  if(!en){ en = {d: today}; ws.push(en); }
  const put = (k, v) => { if(v != null) en[k] = v; else delete en[k]; };
  put('sys', sys); put('dia', dia); put('pulse', pulse); put('sleep', sleep);
  ws.sort((a, b) => a.d < b.d ? -1 : 1);
  await saveStats();
  $('wellModal').classList.remove('open');
  renderWellness();
}

// ---- история самочувствия: та же правка задним числом, что и у веса ----
function openWellHist(){
  const list = $('wellHistList'); list.innerHTML = '';
  wellList().slice(-30).reverse().forEach(en => {
    const row = document.createElement('div');
    row.className = 'wh-row';
    const [y, m, d] = en.d.split('-');
    const inp = (k, st) => `<input type="number" step="${st || 1}" inputmode="decimal" value="${en[k] != null ? en[k] : ''}" data-k="${k}">`;
    const cell = (k, lbl, st) => `<div class="whc"><label>${lbl}</label>${inp(k, st)}</div>`;
    // давление — одна ячейка с двумя полями через косую черту: «Верхнее» и «Нижнее»
    // порознь выглядели как два разных показателя, и строка ехала в две ячейки враскоряку
    row.innerHTML =
      `<div class="wh-top"><b>${+d} ${MONTH_OF[+m - 1]} ${y}</b>` +
      `<button type="button" class="wh-del" title="${esc(t('progress.deleteEntry'))}">${icon('trash')}</button></div>` +
      `<div class="wh-cells wh-well" data-d="${en.d}">` +
        `<div class="whc"><label>${esc(t('progress.pressureShort'))}</label>` +
          `<span class="whp">${inp('sys')}<i>/</i>${inp('dia')}</span></div>` +
        cell('pulse', t('progress.pulseShort')) + cell('sleep', t('well.sleepHours'), 0.5) +
      `</div>`;
    row.querySelector('.wh-del').onclick = ()=> row.classList.toggle('del');
    list.appendChild(row);
  });
  $('wellHistModal').classList.add('open');
}
async function saveWellHist(){
  const ws = wellList();
  [...$('wellHistList').querySelectorAll('.wh-row')].forEach(row => {
    const d = row.querySelector('.wh-cells').dataset.d;
    const i = ws.findIndex(e => e.d === d);
    if(i < 0) return;
    if(row.classList.contains('del')){ ws.splice(i, 1); return; }
    const en = ws[i];
    Object.keys(WELL_LIM).forEach(k => {
      const v = parseFloat(String(row.querySelector(`input[data-k=${k}]`).value).replace(',', '.'));
      if(!isNaN(v) && v >= WELL_LIM[k][0] && v <= WELL_LIM[k][1]) en[k] = Math.round(v * 10) / 10;
      else delete en[k];
    });
    // запись без единого числа — пустая строка в истории, убираем вместе с днём
    if(!Object.keys(en).some(k => k !== 'd')) ws.splice(i, 1);
  });
  ws.sort((a, b) => a.d < b.d ? -1 : 1);
  await saveStats();
  $('wellHistModal').classList.remove('open');
  renderWellness();
}

/* ================= СИНХРОНИЗАЦИЯ С АККАУНТОМ =================
   Локальная копия остаётся основной для тренировки без сети. После подтверждения
   почты Премиум подключает серверный адаптер: сначала принимает изменения с других
   устройств, затем отправляет локальные и оставляет очередь до следующей связи.

   Почему именно это и почему сейчас:

   • ВЕРСИЯ СХЕМЫ у каждого документа. Сервер, получив запись от старой версии
     приложения, должен понимать, надо ли её преобразовать. Проставить версию задним
     числом нельзя: непомеченная запись неотличима от любой другой.
   • ОТМЕТКА ВРЕМЕНИ И НОМЕР РЕДАКЦИИ. Правило «побеждает более поздняя запись»
     не работает, если никто не знает, когда запись сделана. Это тоже не
     восстанавливается задним числом — поэтому заводим до, а не после.
   • ЖУРНАЛ ИЗМЕНЕНИЙ. Каждое сохранение попадает в очередь и доезжает после
     восстановления связи.
   • ИДЕНТИФИКАТОРЫ устройства и профиля. Один аккаунт может содержать несколько
     профилей, а каждое подтверждённое устройство получает собственный ключ доступа.
   • СОГЛАСИЯ С ДАТОЙ И ВЕРСИЕЙ. Когда человек согласился и с какой редакцией
     документа — единственное здесь, что не восстанавливается вообще никак.

   Фотографии в синхронизацию не входят намеренно: самые чувствительные данные,
   самый дорогой трафик и наименьшая польза от переноса между устройствами. */
const SCHEMA_VERSION = 1;
/* Документы, которые поедут на сервер; всё остальное — настройки устройства.

   Единица синхронизации — ОДНА ПРОГРАММА, а не весь их список. Иначе два устройства,
   правящие РАЗНЫЕ программы, растят редакцию одного и того же документа: на сервере
   они конфликтуют целиком, и любое разрешение конфликта теряет чью-то правку.
   Локально программы по-прежнему лежат одним ключом customPrograms — поштучно они
   только УЕЗЖАЮТ. Порядок и состав списка едут отдельным документом 'index': без него
   сервер не отличит «программу удалили» от «программа ещё не доехала». */
const SYNC_KEYS = ['stats'];
const PROGRAM_DOC = id => 'program:' + id;
const isSyncKey = key => SYNC_KEYS.includes(key) || key === 'index' || key.startsWith('program:');
// Короткий хеш строки. Нужен не для защиты, а чтобы понять «изменилось или нет» и не
// гонять на сервер программы, которых человек не трогал.
function docHash(s){
  let h = 5381;
  for(let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(36);
}

const newId = () => (Date.now().toString(36) + Math.random().toString(36).slice(2, 10));

let identity = null;   // {profileId, deviceId, createdAt, email, linkedAt}
let docMeta  = {};     // ключ -> {rev, at, schema}
let outbox   = [];     // [{key, rev, at}] — что ждёт отправки на сервер

// deviceId общий для устройства, profileId — свой у каждого профиля.
//
// Имя поля здесь важнее, чем кажется. Аккаунт на сервере будет ОДИН — почта, подписка,
// оплата, — а профилей внутри него несколько, ведь профили в приложении и есть разные
// люди. Поле, названное accountId, увезло бы эту путаницу в схему базы, и жила бы она
// там годами; переименовать до первого запроса — правка в десять строк, после — миграция
// с данными у всех.
async function loadIdentity(){
  let dev = await kvGet('deviceId');
  if(!dev){ dev = newId(); await kvSet('deviceId', dev); }
  try{ identity = JSON.parse(await kvGet(pk('identity'))) || null; }catch(e){ identity = null; }
  // прежнее имя поля; у тех, кто успел завести личность, оно уже лежит в хранилище
  if(identity && !identity.profileId && identity.accountId){
    identity.profileId = identity.accountId;
    delete identity.accountId;
    await kvSet(pk('identity'), JSON.stringify(identity));
  }
  if(!identity || !identity.profileId){
    identity = {profileId: newId(), createdAt: new Date().toISOString(), email: null, linkedAt: null, consents: {}};
    await kvSet(pk('identity'), JSON.stringify(identity));
  }
  // Серверный id принадлежит профилю, а локальный id — лишь имя его ключей на этом
  // устройстве. Запоминаем связь один раз; профиль, приехавший с сервера, наоборот,
  // диктует identity свой уже существующий id.
  const owner = curUser();
  if(owner && owner.profileId && owner.profileId !== identity.profileId){
    identity.profileId = owner.profileId;
    await kvSet(pk('identity'), JSON.stringify(identity));
  } else if(owner && !owner.profileId){
    owner.profileId = identity.profileId;
    await saveUsers();
  }
  if(!identity.consents) identity.consents = {};
  identity.deviceId = dev;
  // отметки, поставленные до создания профиля, переносим на него — но не затираем
  // уже существующие: повторное знакомство не должно сдвигать дату первого согласия
  if(pendingConsents.length){
    pendingConsents.forEach(({kind, rec}) => { if(!identity.consents[kind]) identity.consents[kind] = rec; });
    pendingConsents = [];
    await kvSet(pk('identity'), JSON.stringify(identity));
  }
  try{ docMeta = JSON.parse(await kvGet(pk('docMeta'))) || {}; }catch(e){ docMeta = {}; }
  try{ outbox  = JSON.parse(await kvGet(pk('outbox')))  || []; }catch(e){ outbox  = []; }
}
async function saveIdentity(){ await kvSet(pk('identity'), JSON.stringify(identity)); }

// Поднять редакцию документа и поставить его в очередь. Очередь схлопывается по ключу —
// на сервер уедет последнее состояние, а не история правок.
function bumpDoc(key, extra){
  const prev = docMeta[key] || {rev: 0};
  const at = new Date().toISOString();
  docMeta[key] = Object.assign({rev: prev.rev + 1, at, schema: SCHEMA_VERSION}, extra || {});
  outbox = outbox.filter(o => o.key !== key);
  outbox.push({key, rev: docMeta[key].rev, at});
}
async function flushMeta(){
  await kvSet(pk('docMeta'), JSON.stringify(docMeta));
  await kvSet(pk('outbox'), JSON.stringify(outbox));
}

// Одно сохранение документа: пишем значение, поднимаем редакцию, ставим в очередь.
async function saveDoc(key, value){
  await kvSet(pk(key), JSON.stringify(value));
  if(!isSyncKey(key)) return;
  bumpDoc(key);
  await flushMeta();
  queueAccountSync();
}

// Что уедет на сервер под этим ключом. Программы лежат в памяти одним списком, поэтому
// значение документа собирается здесь, а не читается из хранилища по имени ключа.
// null — это НАДГРОБИЕ: программу удалили, и сервер должен об этом узнать.
async function docValue(key){
  if(key === 'index') return JSON.stringify({order: customPrograms.map(p => p.id)});
  if(key.startsWith('program:')){
    const id = key.slice('program:'.length);
    const p = customPrograms.find(x => String(x.id) === id);
    return p ? JSON.stringify(p) : null;
  }
  return await kvGet(pk(key));
}

// Единый шов обмена с сервером. Пока нет аккаунта, Премиума или сети, адаптера нет:
// приложение продолжает работать локально, а очередь ждёт следующего подключения.
// Переезд существующего пользователя на сервер. Руками ничего выгружать и заливать не
// нужно и не будет нужно: при первом подключении всё, что уже лежит на телефоне,
// помечается изменённым и уходит наверх обычной очередью — тем же путём, что и правки,
// сделанные офлайн. Резервная копия файлом остаётся отдельной ручной функцией.
async function markAllForSync(){
  for(const key of SYNC_KEYS) bumpDoc(key);
  for(const p of customPrograms) bumpDoc(PROGRAM_DOC(p.id), {h: docHash(JSON.stringify(p))});
  bumpDoc('index', {h: docHash(customPrograms.map(p => p.id).join(','))});
  await flushMeta();
}

const SYNC = {
  adapter: null,
  get connected(){ return !!SYNC.adapter; },
  // единственная точка входа для серверного адаптера
  async connect(adapter){
    SYNC.adapter = adapter;
    if(adapter.pull) await adapter.pull();
    await markAllForSync();
    return SYNC.push();
  },
  pending(){ return outbox.length; },
  async push(){
    // без личности отправлять некуда и незачем: профиль ещё не заведён
    if(!SYNC.adapter || !identity) return {sent: 0, offline: true};
    const batch = outbox.slice();
    // Значения собираем ЗДЕСЬ и через await. docValue асинхронная, и без await на сервер
    // уехал бы список промисов вместо документов — молча, потому что JSON.stringify
    // превращает промис в пустой объект.
    const payload = [];
    for(const o of batch){
      const value = await docValue(o.key);
      // Надгробие бывает только у программы. У обычного ключа пустое значение означает
      // «ещё ни разу не сохраняли», а не «удалили»: отправить его как удаление — значит
      // стереть на сервере статистику, которой человек просто пока не набрал.
      const gone = value === null && o.key.startsWith('program:');
      if(value === null && !gone) continue;
      payload.push({
        key: o.key, rev: o.rev, at: o.at, schema: SCHEMA_VERSION,
        profileId: identity.profileId, deviceId: identity.deviceId,
        deleted: gone, value
      });
    }
    if(payload.length) await SYNC.adapter.push(payload);
    outbox = outbox.filter(o => !batch.find(b => b.key === o.key && b.rev === o.rev));
    await kvSet(pk('outbox'), JSON.stringify(outbox));
    return {sent: batch.length};
  }
};

/* Серверный адаптер аккаунта. Ключ выдаётся только после кода на почту и отдельный
   для каждого устройства. Фото-прогресс здесь отсутствует даже как возможный ключ:
   на сервер уходят только stats, index и program:<id>. */
let syncTimer = null;
let syncBusy = null;
let syncReplaceLocal = false;
let syncState = 'idle';

function showSyncState(state){
  syncState = state;
  const el = $('accSync');
  if(!el) return;
  if(!account || !account.email) el.textContent = '';
  else if(!isPremium()) el.textContent = t('sync.premiumOnly');
  else if(state === 'busy') el.textContent = t('sync.busy');
  else if(state === 'ok') el.textContent = t('sync.ok');
  else if(state === 'error') el.textContent = t('sync.error');
  else el.textContent = t('sync.account');
}

const accountAuth = () => ({
  email: (account && account.email) || '',
  token: (account && account.syncToken) || '',
  deviceId: (identity && identity.deviceId) || ''
});
const syncAuth = action => Object.assign({action}, accountAuth());
const syncProfileInt = (value, def, lo, hi) => {
  const n = Number(value);
  return Number.isFinite(n) ? Math.max(lo, Math.min(hi, Math.round(n))) : def;
};
const syncUser = u => ({
  id:u.profileId || u.id, name:u.name || '', gender:u.gender || '', age:profileAge(u),
  theme:u.theme || 'system',
  locale:profileLocalePreference(u),
  prepSec:syncProfileInt(u.prepSec, 5, 0, 30),
  readySec:syncProfileInt(u.readySec, 5, 0, 30),
  sideSec:syncProfileInt(u.sideSec, 10, 3, 60),
  voiceVol:syncProfileInt(u.voiceVol, 100, 0, 100),
  fxVol:syncProfileInt(u.fxVol, 100, 0, 100)
});
const remoteWins = (remote, local) => {
  if(!local) return true;
  const a = Date.parse(remote.at || '') || 0, b = Date.parse(local.at || '') || 0;
  if(a !== b) return a > b;
  return String(remote.deviceId || '') > String(local.deviceId || '');
};
const parsed = (raw, fallback) => { try{ return raw == null ? fallback : JSON.parse(raw); }catch(e){ return fallback; } };

const isPlaceholderProfile = u => {
  const name = String((u && u.name) || '').trim().toLowerCase();
  return (!name || name === 'мой профиль' || /^профиль\s*\d*$/.test(name))
    && !(u && u.gender) && !profileAge(u);
};
function remoteProfileHasData(r){
  return (r && Array.isArray(r.docs) ? r.docs : []).some(d => {
    if(!d || d.deleted) return false;
    if(String(d.key || '').startsWith('program:')){
      const p = parsed(d.value, null);
      return !!(p && p.id !== 'warmup');
    }
    if(d.key === 'index') return (parsed(d.value, {}).order || []).some(id => id !== 'warmup');
    if(d.key === 'stats'){
      const s = parsed(d.value, {});
      return (s.history || []).length > 0 || (+s.count || +s.totalSec || 0) > 0;
    }
    return false;
  });
}
async function localProfileHasData(uid){
  const programs = parsed(await kvGet('customPrograms_' + uid), []);
  const s = parsed(await kvGet('stats_' + uid), {});
  const photos = parsed(await kvGet('photos_' + uid), []);
  return (Array.isArray(programs) && programs.some(p => p && p.id !== 'warmup'))
    || (Array.isArray(s.history) && s.history.length > 0)
    || (+s.count || +s.totalSec || 0) > 0
    || (Array.isArray(photos) && photos.length > 0);
}

async function collapseEmptyLocalProfiles(active){
  const blanks = [];
  for(const u of users){
    if(isPlaceholderProfile(u) && !(await localProfileHasData(u.id))) blanks.push(u);
  }
  if(blanks.length < 2) return;
  const remoteIds = new Set((active || []).map(r => r.user && r.user.id).filter(Boolean));
  const keep = blanks.find(u => remoteIds.has(u.profileId || u.id))
    || blanks.find(u => u.id === currentUser) || blanks[0];
  for(const u of blanks){
    if(u === keep) continue;
    for(const k of PROFILE_KEYS) await kvDel(k + '_' + u.id);
  }
  users = users.filter(u => !blanks.includes(u) || u === keep);
  if(!users.some(u => u.id === currentUser)) currentUser = keep.id;
}

function mergeStatsDocs(local, remote, preferRemote){
  const a = local && typeof local === 'object' ? local : {};
  const b = remote && typeof remote === 'object' ? remote : {};
  const older = preferRemote ? a : b, newerDoc = preferRemote ? b : a;
  const out = Object.assign({}, older, newerDoc);
  const unite = (x, y, key) => {
    const map = new Map();
    (Array.isArray(x) ? x : []).concat(Array.isArray(y) ? y : []).forEach(v => {
      const k = key(v);
      if(k) map.set(k, v);
    });
    return [...map.values()];
  };
  out.history = unite(older.history, newerDoc.history, h => h && (h.id
    ? 'id:' + h.id
    : [h.d||'',h.t??'',h.pid||'',h.sec||0,h.plan||0].join('|')))
    .sort((x,y) => String(x.d||'').localeCompare(String(y.d||'')) || (+x.t||0)-(+y.t||0));
  out.weights = unite(older.weights, newerDoc.weights, x => x && (x.d || JSON.stringify(x)));
  out.wellness = unite(older.wellness, newerDoc.wellness, x => x && (x.d || JSON.stringify(x)));
  out.badges = [...new Set([].concat(b.badges || [], a.badges || []))];
  out.totalSec = out.history.length ? out.history.reduce((n,h)=>n+(+h.sec||0),0) : Math.max(+a.totalSec||0,+b.totalSec||0);
  out.count = out.history.length || Math.max(+a.count||0,+b.count||0);
  out.bestStreak = Math.max(+a.bestStreak||0,+b.bestStreak||0);
  out.totalKg = Math.max(+a.totalKg||0,+b.totalKg||0);
  out.hfDone = Math.max(+a.hfDone||0,+b.hfDone||0);
  return out;
}

async function applyRemoteSync(result){
  await applyRemoteAccountDocs(result);
  const remote = Array.isArray(result && result.profiles) ? result.profiles : [];
  if(!remote.length) return;
  let active = remote.filter(r => !r.deleted);

  // Старый клиент мог несколько раз выгрузить технический пустой «Мой профиль».
  // Содержательные профили никогда не склеиваем; среди пустых оставляем один, а
  // остальные отправляем на сервер как удалённые, чтобы они не возвращались.
  const emptyRemote = active.filter(r => isPlaceholderProfile(r.user) && !remoteProfileHasData(r));
  if(emptyRemote.length > 1){
    emptyRemote.sort((a,b) => String(b.userAt || '').localeCompare(String(a.userAt || '')));
    const keepId = emptyRemote[0].user.id;
    const drop = new Set(emptyRemote.slice(1).map(r => r.user.id));
    active = active.filter(r => !drop.has(r.user && r.user.id));
    if(!Array.isArray(account.deletedProfiles)) account.deletedProfiles = [];
    drop.forEach(id => {
      if(!account.deletedProfiles.some(x => x.id === id)) account.deletedProfiles.push({id, at:new Date().toISOString()});
    });
    await saveAccount();
  }
  await collapseEmptyLocalProfiles(active);

  if(syncReplaceLocal){
    if(active.length){
      users = active.map(r => Object.assign(syncUser(r.user || {}), {profileId:r.user.id, photo:null, syncAt:r.userAt || ''}));
      currentUser = users[0].id;
      await saveUsers();
      await kvSet('currentUser', currentUser);
    }
    syncReplaceLocal = false;
  } else {
    // До первой серверной версии один и тот же человек мог получить разные
    // profileId на двух телефонах. Единственное точное совпадение анкеты связываем
    // с уже приехавшим id; неоднозначные совпадения оставляем разными профилями.
    const claimed = new Set(users.map(u => u.profileId || u.id));
    users.forEach(u => {
      if(active.some(r => r.user && r.user.id === (u.profileId || u.id))) return;
      const same = active.filter(r => !claimed.has(r.user.id)
        && (r.user.name || '') === (u.name || '')
        && (r.user.gender || '') === (u.gender || '')
        && profileAge(r.user) === profileAge(u));
      if(same.length === 1){ u.profileId = same[0].user.id; claimed.add(u.profileId); }
    });
    active.forEach(r => {
      const ru = r.user || {};
      const i = users.findIndex(u => (u.profileId || u.id) === ru.id);
      if(i < 0) users.push(Object.assign(syncUser(ru), {id:ru.id, profileId:ru.id, photo:null, syncAt:r.userAt || ''}));
      else if(!users[i].syncAt || String(r.userAt || '') >= String(users[i].syncAt || '')){
        const old = users[i], photo = old.photo || null;
        users[i] = Object.assign({}, old, syncUser(ru), {id:old.id, profileId:ru.id, photo, syncAt:r.userAt || ''});
      }
    });
    await saveUsers();
  }

  // Удаление профиля тоже синхронизируется. Сервер хранит надгробие, поэтому
  // выключенный телефон не воскресит профиль старой копией при следующем входе.
  for(const rp of remote.filter(r => r.deleted)){
    const i = users.findIndex(u => (u.profileId || u.id) === (rp.user && rp.user.id));
    if(i < 0 || users.length <= 1) continue;
    if(users[i].syncAt && String(users[i].syncAt) > String(rp.userAt || '')) continue;
    const id = users[i].id;
    for(const k of PROFILE_KEYS) await kvDel(k + '_' + id);
    users.splice(i, 1);
  }
  await saveUsers();

  for(const rp of active){
    const pid = rp.user && rp.user.id;
    if(!pid) continue;
    const localUser = users.find(u => (u.profileId || u.id) === pid);
    const localId = localUser ? localUser.id : pid;
    if((await kvGet('identity_' + localId)) === null){
      await kvSet('identity_' + localId, JSON.stringify({profileId:pid, createdAt:new Date().toISOString(),
        email:account.email, linkedAt:new Date().toISOString(), consents:{}}));
    }
    let meta = parsed(await kvGet('docMeta_' + localId), {});
    let queue = parsed(await kvGet('outbox_' + localId), []);
    let progs = parsed(await kvGet('customPrograms_' + localId), []);
    let stat = parsed(await kvGet('stats_' + localId), null);
    let order = null, programsTouched = false, mergedStats = false;
    const byId = new Map((Array.isArray(progs) ? progs : []).map(p => [String(p.id), p]));

    for(const d of (rp.docs || [])){
      if(!isSyncKey(d.key)) continue;
      if(d.key === 'stats'){
        const incoming = parsed(d.value, {totalSec:0});
        if(stat && JSON.stringify(stat) !== JSON.stringify(incoming)){
          stat = mergeStatsDocs(stat, incoming, remoteWins(d, meta[d.key])); mergedStats = true;
        } else if(!stat || remoteWins(d, meta[d.key])) stat = incoming;
        else continue;
        await kvSet('stats_' + localId, JSON.stringify(stat));
      } else {
        if(!remoteWins(d, meta[d.key])) continue;
        if(d.key === 'index'){
          order = parsed(d.value, {}).order || [];
        } else if(d.key.startsWith('program:')){
          const id = d.key.slice(8);
          if(d.deleted) byId.delete(id);
          else {
            const p = parsed(d.value, null);
            if(p) byId.set(id, p);
          }
          programsTouched = true;
        }
      }
      meta[d.key] = {rev:+d.rev||1, at:d.at, schema:+d.schema||1,
                     deviceId:d.deviceId||'', gone:!!d.deleted,
                     h:d.value == null ? '' : docHash(String(d.value))};
      queue = queue.filter(o => o.key !== d.key);
    }

    if(programsTouched || order){
      const ids = Array.isArray(order) ? order.map(String) : [];
      progs = ids.map(id => byId.get(id)).filter(Boolean);
      byId.forEach((p,id) => { if(!ids.includes(id)) progs.push(p); });
      // Счёт прохождений восстанавливаем из объединённой истории: две законченные
      // тренировки на двух телефонах должны дать два повышения, а не победителя LWW.
      const history = (stat && stat.history) || [];
      progs.forEach(p => {
        const n = history.filter(h => String(h.pid || '') === String(p.id)).length;
        if(n){ p.stats = p.stats || {}; p.stats.completions = Math.max(+p.stats.completions||0, n); }
      });
      await kvSet('customPrograms_' + localId, JSON.stringify(progs));
    }
    if(mergedStats){
      const at = new Date().toISOString();
      meta.stats = {rev:(+meta.stats.rev||0)+1, at, schema:SCHEMA_VERSION};
      queue = queue.filter(o => o.key !== 'stats').concat([{key:'stats',rev:meta.stats.rev,at}]);
    }
    await kvSet('docMeta_' + localId, JSON.stringify(meta));
    await kvSet('outbox_' + localId, JSON.stringify(queue));
  }

  if(!users.some(u => u.id === currentUser)) currentUser = users[0].id;
  await kvSet('currentUser', currentUser);
  await setAppLocale(profileLocalePreference(curUser()), {persist:false});
  await loadIdentity();
  identity.email = account.email;
  await saveIdentity();
  await loadData();
  await loadPhotos();
  await ensureWarmup();
  applyProgressionAll();
  renderUsers(); renderMine(); renderStats(); renderWeight(); renderWellness(); renderPhotos();
}

function trainerSyncValue(value){
  const out = Object.assign({}, value || {});
  delete out.key;
  delete out.pageErr;
  return out;
}
function mergeClientLists(localList, remoteList, preferRemote){
  const out = new Map();
  const add = (c, preferred) => {
    if(!c || !c.id) return;
    const old = out.get(c.id);
    if(!old){ out.set(c.id, JSON.parse(JSON.stringify(c))); return; }
    const merged = Object.assign({}, preferred ? old : c, preferred ? c : old);
    const progs = new Map();
    [].concat(old.progs || [], c.progs || []).forEach(p => {
      const key = String((p && p.pid) || (p && p.link && p.link.id) || '');
      if(key) progs.set(key, Object.assign({}, progs.get(key) || {}, p));
    });
    merged.progs = [...progs.values()];
    out.set(c.id, merged);
  };
  (Array.isArray(localList) ? localList : []).forEach(c => add(c, false));
  (Array.isArray(remoteList) ? remoteList : []).forEach(c => add(c, !!preferRemote));
  return [...out.values()];
}
async function applyRemoteAccountDocs(result){
  if(!account || !account.email) return;
  const docs = Array.isArray(result && result.accountDocs) ? result.accountDocs : [];
  if(!docs.length) return;
  const rec = await readAccountBucket();
  if(!rec.bucket.meta) rec.bucket.meta = {};
  for(const d of docs){
    if(!d || !['trainer','clients','notificationPrefs'].includes(d.key) || d.deleted) continue;
    const localMeta = rec.bucket.meta[d.key];
    const takeRemote = !localMeta || remoteWins(d, localMeta);
    const incoming = parsed(d.value, d.key === 'clients' ? [] : {});
    if(d.key === 'trainer'){
      if(!takeRemote) continue;
      const keep = rec.bucket.trainer || trainer || {};
      rec.bucket.trainer = Object.assign({}, incoming || {});
      // Ключ управления страницей никогда не хранится в синхронизации. Ник,
      // подтверждённый входом, тоже важнее старой копии документа.
      if(keep.key) rec.bucket.trainer.key = keep.key;
      if(keep.handle) rec.bucket.trainer.handle = keep.handle;
      if(keep.on && keep.handle) rec.bucket.trainer.on = true;
      rec.bucket.meta[d.key] = {rev:+d.rev || 1, at:d.at || '', schema:+d.schema || 1,
                                deviceId:d.deviceId || ''};
    } else if(d.key === 'clients'){
      rec.bucket.clients = mergeClientLists(rec.bucket.clients || clients, incoming, takeRemote);
      if(takeRemote) rec.bucket.meta[d.key] = {rev:+d.rev || 1, at:d.at || '', schema:+d.schema || 1,
                                               deviceId:d.deviceId || ''};
    } else if(takeRemote){
      rec.bucket.notificationPrefs = Object.assign({}, incoming || {});
      rec.bucket.meta[d.key] = {rev:+d.rev || 1, at:d.at || '', schema:+d.schema || 1,
                                deviceId:d.deviceId || ''};
      try{
        if(typeof NOTIFICATION_PREF_DEFAULTS !== 'undefined'){
          localStorage.setItem(NOTIFICATION_PREFS_KEY, JSON.stringify(
            Object.assign({}, NOTIFICATION_PREF_DEFAULTS, rec.bucket.notificationPrefs)
          ));
        }
      }catch(_){}
    }
  }
  await writeAccountBucket(rec);
  trainer = rec.bucket.trainer || trainer;
  clients = Array.isArray(rec.bucket.clients) ? rec.bucket.clients : clients;
  if(typeof syncNotificationSettings === 'function') syncNotificationSettings();
}

async function accountDocsSnapshot(){
  if(!account || !account.email) return [];
  const rec = await readAccountBucket();
  if(!rec.bucket.meta) rec.bucket.meta = {};
  const now = new Date().toISOString();
  let localNotificationPrefs = {};
  try{
    localNotificationPrefs = (typeof getNotificationPrefs === 'function')
      ? getNotificationPrefs()
      : parsed(localStorage.getItem('fitNotificationPrefsV1'), {});
  }catch(_){}
  if(!rec.bucket.notificationPrefs) rec.bucket.notificationPrefs = localNotificationPrefs;
  const values = {
    trainer:trainerSyncValue(rec.bucket.trainer || trainer),
    clients:Array.isArray(rec.bucket.clients) ? rec.bucket.clients : clients,
    notificationPrefs:Object.assign({}, rec.bucket.notificationPrefs || localNotificationPrefs)
  };
  const docs = [];
  for(const key of ['trainer','clients','notificationPrefs']){
    if(!rec.bucket.meta[key]) rec.bucket.meta[key] = {rev:1, at:account.linkedAt || now, schema:SCHEMA_VERSION};
    const m = rec.bucket.meta[key];
    docs.push({key, profileId:'__account__', rev:m.rev || 1, at:m.at || now,
               schema:m.schema || SCHEMA_VERSION, value:JSON.stringify(values[key] || (key === 'clients' ? [] : {}))});
  }
  await writeAccountBucket(rec);
  return docs;
}

async function syncNotificationPrefsServer(action){
  if(!account || !account.email || !account.syncToken) return false;
  let deviceId = await kvGet('deviceId');
  if(!deviceId){ deviceId = newId(); await kvSet('deviceId', deviceId); }
  const base = {action:action || 'push', email:account.email, deviceId, token:account.syncToken};
  if(base.action === 'pull'){
    const result = await apiPost('/api/sync', base);
    await applyRemoteAccountDocs(result);
    return true;
  }
  const rec = await readAccountBucket();
  if(!rec.bucket.meta) rec.bucket.meta = {};
  const key = 'notificationPrefs';
  if(!rec.bucket.notificationPrefs && typeof getNotificationPrefs === 'function'){
    rec.bucket.notificationPrefs = getNotificationPrefs();
  }
  if(!rec.bucket.meta[key]) bumpAccountMeta(rec.bucket, key);
  const m = rec.bucket.meta[key];
  const doc = {key, profileId:'__account__', rev:m.rev || 1, at:m.at || new Date().toISOString(),
    schema:m.schema || SCHEMA_VERSION, value:JSON.stringify(rec.bucket.notificationPrefs || {})};
  await writeAccountBucket(rec);
  await apiPost('/api/sync', Object.assign(base, {profiles:[], docs:[doc]}));
  return true;
}

async function pushAccountDocs(){
  if(!account || !account.email || !account.syncToken || !isPremium()) return;
  const base = syncAuth('push');
  for(const doc of await accountDocsSnapshot()){
    await apiPost('/api/sync', Object.assign(base, {profiles:[], docs:[doc]}));
  }
}

async function profileSnapshot(uid){
  const u = users.find(x => x.id === uid);
  if(!u) return null;
  const programs = parsed(await kvGet('customPrograms_' + uid), []);
  const meta = parsed(await kvGet('docMeta_' + uid), {});
  const ident = parsed(await kvGet('identity_' + uid), {});
  const now = new Date().toISOString();
  const serverId = u.profileId || u.id;
  const docs = [];
  const add = (key, value) => {
    if(value == null) return;
    const m = meta[key] || {rev:1, at:now, schema:SCHEMA_VERSION};
    docs.push({key, profileId:serverId, rev:m.rev||1, at:m.at||now, schema:m.schema||SCHEMA_VERSION,
               deleted:!!m.gone, value:m.gone ? null : JSON.stringify(value)});
  };
  add('stats', parsed(await kvGet('stats_' + uid), null));
  (Array.isArray(programs) ? programs : []).forEach(p => add(PROGRAM_DOC(p.id), p));
  add('index', {order:(Array.isArray(programs) ? programs : []).map(p => p.id)});
  return {profile:{user:syncUser(u), at:u.syncAt || ident.createdAt || '1970-01-01T00:00:00.000Z'}, docs};
}

const accountSyncAdapter = {
  async push(payload){
    const base = syncAuth('push');
    const u = curUser();
    await apiPost('/api/sync', Object.assign(base, {profiles:[{user:syncUser(u), at:u.syncAt || identity.createdAt}], docs:[]}));
    // По одному документу: программа может содержать свои картинки и быть крупной;
    // общий пакет тогда упирается в предел запроса, хотя каждый документ допустим.
    for(const doc of payload) await apiPost('/api/sync', Object.assign(base, {profiles:[], docs:[doc]}));
    showSyncState('ok');
  },
  async pull(){
    const result = await apiPost('/api/sync', syncAuth('pull'));
    await applyRemoteSync(result);
    return result;
  }
};

async function pushAllProfiles(){
  const base = syncAuth('push');
  for(const u of users){
    const snap = await profileSnapshot(u.id);
    if(!snap) continue;
    await apiPost('/api/sync', Object.assign(base, {profiles:[snap.profile], docs:[]}));
    for(const doc of snap.docs) await apiPost('/api/sync', Object.assign(base, {profiles:[], docs:[doc]}));
  }
}

async function pushDeletedProfiles(){
  const list = Array.isArray(account.deletedProfiles) ? account.deletedProfiles.slice() : [];
  if(!list.length) return;
  const base = syncAuth('push');
  for(const rec of list){
    await apiPost('/api/sync', Object.assign(base, {profiles:[{user:{id:rec.id}, at:rec.at, deleted:true}], docs:[]}));
  }
  account.deletedProfiles = [];
  await saveAccount();
}

async function connectAccountSync(opts){
  if(!account || !account.email || !account.syncToken || !identity){
    showSyncState('idle');
    return false;
  }
  if(!isPremium()){
    try{ await syncNotificationPrefsServer('pull'); }catch(_){}
    showSyncState('idle');
    return false;
  }
  if(syncBusy) return syncBusy;
  syncReplaceLocal = !!(opts && opts.replaceLocal);
  showSyncState('busy');
  syncBusy = (async()=>{
    try{
      SYNC.adapter = accountSyncAdapter;
      await pushDeletedProfiles();          // удаление должно дойти до pull, иначе профиль воскреснет
      await accountSyncAdapter.pull();        // сначала вернуть серверное, потом отправлять местное
      await pushDeletedProfiles();          // pull мог найти и схлопнуть старые пустые дубликаты
      await pushAllProfiles();
      await pushAccountDocs();
      await SYNC.push();                      // в том числе надгробия удалённых программ
      await loadIdentity();
      await loadData();
      renderUsers(); renderMine(); renderStats(); renderWeight(); renderWellness(); renderPhotos();
      applyThemeFor(curUser());
      showSyncState('ok');
      return true;
    }catch(e){ showSyncState('error'); return false; }
    finally{ syncBusy = null; }
  })();
  return syncBusy;
}

function queueAccountSync(){
  if(!account || !account.email || !account.syncToken || !isPremium()) return;
  clearTimeout(syncTimer);
  syncTimer = setTimeout(()=>{
    showSyncState('busy');
    if(SYNC.adapter) Promise.all([SYNC.push(), pushAccountDocs()]).catch(()=> showSyncState('error'));
    else connectAccountSync().catch(()=> showSyncState('error'));
  }, 900);
}

// На новой установке загрузчик создаёт технический «Профиль 1», поэтому users.length
// уже равен единице ещё до входа. Проверяем содержимое: только совершенно пустую
// заглушку можно заменить серверными профилями. Реальные локальные данные объединяем.
async function hasMeaningfulLocalData(){
  if(users.length !== 1) return users.length > 0;
  const u = users[0] || {};
  if(!isPlaceholderProfile(u) || u.photo) return true;
  const uid = u.id;
  return localProfileHasData(uid);
}

// Согласия: что именно, какой редакции и когда. Версию поднимаем при правке текстов —
// иначе нельзя доказать, с какой редакцией человек соглашался.
const CONSENT_VERSION = 1;
// Согласие с правилами человек даёт на первом шаге знакомства — а профиля, и значит
// личности, в этот момент ещё нет: он создаётся на последнем шаге. Молча терять такую
// отметку нельзя, восстановить её потом неоткуда. Копим до появления личности.
let pendingConsents = [];
async function recordConsent(kind){
  const rec = {v: CONSENT_VERSION, at: new Date().toISOString()};
  if(!identity){ pendingConsents.push({kind, rec}); return; }
  identity.consents[kind] = rec;
  await saveIdentity();
}
const hasConsent = kind => !!(identity && identity.consents && identity.consents[kind]);

// Программы хранятся одним ключом, а в очередь встают поштучно: на сервер уйдут только
// те, что человек действительно тронул. Хеш программы лежит рядом с её редакцией —
// без него каждое сохранение любой программы гнало бы наверх весь список.
async function savePrograms(){
  await kvSet(pk('customPrograms'), JSON.stringify(customPrograms));
  let touched = false;
  const live = new Set();
  for(const p of customPrograms){
    const key = PROGRAM_DOC(p.id);
    live.add(key);
    const h = docHash(JSON.stringify(p));
    const prev = docMeta[key];
    if(prev && prev.h === h && !prev.gone) continue;
    bumpDoc(key, {h});
    touched = true;
  }
  // удалённая программа — тоже документ: без надгробия она вернётся с другого устройства
  for(const key of Object.keys(docMeta)){
    if(!key.startsWith('program:') || live.has(key) || docMeta[key].gone) continue;
    bumpDoc(key, {gone: true});
    touched = true;
  }
  const order = docHash(customPrograms.map(p => p.id).join(','));
  if(!docMeta.index || docMeta.index.h !== order){ bumpDoc('index', {h: order}); touched = true; }
  if(touched){ await flushMeta(); queueAccountSync(); }
}
